import { connect, type NatsConnection } from "nats";
import { logger } from "./logger";
export async function connectNats(url: string): Promise<NatsConnection> {
  const nc = await connect({ servers: url, maxReconnectAttempts: -1 });
  logger.info({ url }, "NATS connected");
  return nc;
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const HACCPEventSchema = z.object({
  tenantId: z.string().uuid(),
  locationId: z.string().uuid(),
  ccpId: z.string(),
  eventType: z.enum([
    "ccp.measurement", "ccp.deviation", "ccp.corrective-action",
    "ccp.verification", "prerequisite.failure", "sanitation.completed",
    "pest.detected", "allergen.incident", "employee.illness.report",
    "foreign-object.found", "recall.initiated", "supplier.rejection",
  ]),
  measurement: z.number().optional(),
  unit: z.string().optional(),
  criticalLimit: z.object({ min: z.number().optional(), max: z.number().optional() }).optional(),
  correctionTaken: z.string().optional(),
  payload: z.record(z.unknown()).default({}),
});

const SupplierInspectionSchema = z.object({
  tenantId: z.string().uuid(),
  locationId: z.string().uuid(),
  supplierId: z.string().uuid(),
  deliveryId: z.string().uuid(),
  inspectedBy: z.string(),
  passed: z.boolean(),
  items: z.array(z.object({
    itemId: z.string(),
    description: z.string(),
    temperature: z.number().optional(),
    condition: z.enum(["acceptable", "borderline", "rejected"]),
    notes: z.string().optional(),
  })),
  overallResult: z.enum(["accepted", "partially-accepted", "rejected"]),
});

export async function registerRoutes(app: FastifyInstance) {
  const nats = (app as any).nats;

  // POST /adapter/foodservice/haccp-events — HACCP control point measurements
  app.post("/adapter/foodservice/haccp-events", async (req, reply) => {
    const parsed = HACCPEventSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const {
      tenantId, locationId, ccpId, eventType,
      measurement, unit, criticalLimit, correctionTaken, payload,
    } = parsed.data;

    const isDeviation = eventType.includes("deviation") || eventType.includes("failure");
    const isHighSeverity = eventType.includes("allergen") ||
      eventType.includes("foreign-object") || eventType.includes("pest") ||
      eventType.includes("illness");

    let severity: "low" | "medium" | "high" | "critical" = "low";
    if (isHighSeverity) severity = "high";
    else if (isDeviation) severity = "medium";
    if (eventType === "recall.initiated") severity = "critical";

    const outOfLimit = measurement != null && criticalLimit && (
      (criticalLimit.min != null && measurement < criticalLimit.min) ||
      (criticalLimit.max != null && measurement > criticalLimit.max)
    );

    if (outOfLimit) severity = severity === "low" ? "medium" : "high";

    const eventId = randomUUID();
    const envelope = {
      id: eventId,
      tenantId,
      entityType: "ccp",
      entityId: ccpId,
      eventType,
      facilityId: locationId,
      severity,
      payload: {
        locationId, ccpId, measurement, unit, criticalLimit,
        outOfLimit, correctionTaken, adapterSource: "vertical-foodservice",
        ...payload,
      },
      sourceSystem: "foodservice-adapter",
      ts: new Date().toISOString(),
    };

    // All HACCP events go to provenance for immutable record
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify(envelope)));

    // Deviations and high-severity events go to food defense
    if (isDeviation || isHighSeverity || severity === "critical" || outOfLimit) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify(envelope)));
    }

    nats.publish("atlas.adapter.foodservice.haccp-event", Buffer.from(JSON.stringify(envelope)));

    return reply.code(202).send({ id: eventId, severity, outOfLimit, accepted: true });
  });

  // POST /adapter/foodservice/supplier-inspection
  app.post("/adapter/foodservice/supplier-inspection", async (req, reply) => {
    const parsed = SupplierInspectionSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { tenantId, locationId, supplierId, deliveryId, inspectedBy, passed, items, overallResult } = parsed.data;
    const inspectionId = randomUUID();

    const rejectedItems = items.filter((i) => i.condition === "rejected");

    // Provenance record for the full inspection
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify({
      id: inspectionId,
      tenantId,
      entityType: "delivery",
      entityId: deliveryId,
      eventType: "supplier.inspection",
      actorId: inspectedBy,
      facilityId: locationId,
      payload: {
        supplierId, overallResult, passed, itemCount: items.length,
        rejectedCount: rejectedItems.length, adapterSource: "vertical-foodservice",
      },
      sourceSystem: "foodservice-adapter",
      ts: new Date().toISOString(),
    })));

    // Trigger food defense if items were rejected
    if (!passed || rejectedItems.length > 0) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify({
        id: randomUUID(),
        tenantId,
        facilityId: locationId,
        entityType: "delivery",
        entityId: deliveryId,
        eventType: "supplier.rejection",
        severity: overallResult === "rejected" ? "high" : "medium",
        payload: { supplierId, rejectedItems, overallResult, adapterSource: "vertical-foodservice" },
        sourceSystem: "foodservice-adapter",
        ts: new Date().toISOString(),
      })));
    }

    return reply.code(202).send({ id: inspectionId, overallResult, rejectedItems: rejectedItems.length });
  });

  // POST /adapter/foodservice/sanitation-log
  app.post("/adapter/foodservice/sanitation-log", async (req, reply) => {
    const body = req.body as {
      tenantId: string;
      locationId: string;
      areaId: string;
      sanitizedBy: string;
      method: string;
      chemicals: string[];
      passedVerification: boolean;
      nextScheduledAt?: string;
    };

    const logId = randomUUID();
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify({
      id: logId,
      tenantId: body.tenantId,
      entityType: "sanitation-area",
      entityId: body.areaId,
      eventType: "sanitation.completed",
      actorId: body.sanitizedBy,
      facilityId: body.locationId,
      payload: {
        method: body.method, chemicals: body.chemicals,
        passedVerification: body.passedVerification,
        nextScheduledAt: body.nextScheduledAt,
        adapterSource: "vertical-foodservice",
      },
      sourceSystem: "foodservice-adapter",
      ts: new Date().toISOString(),
    })));

    if (!body.passedVerification) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify({
        id: randomUUID(),
        tenantId: body.tenantId,
        facilityId: body.locationId,
        eventType: "sanitation.verification-failure",
        severity: "medium",
        payload: { areaId: body.areaId, method: body.method },
        sourceSystem: "foodservice-adapter",
        ts: new Date().toISOString(),
      })));
    }

    return reply.code(202).send({ id: logId, accepted: true });
  });
}

import { connect, type NatsConnection } from "nats";
import { logger } from "./logger";
export async function connectNats(url: string): Promise<NatsConnection> {
  const nc = await connect({ servers: url, maxReconnectAttempts: -1 });
  logger.info({ url }, "NATS connected");
  return nc;
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const FoodServiceEventSchema = z.object({
  tenantId: z.string().uuid(),
  facilityId: z.string().uuid(),
  patientUnitId: z.string().optional(),
  eventType: z.enum([
    "meal.prepared", "meal.delivered", "meal.rejected", "meal.wasted",
    "allergen.incident", "dietary.violation", "temperature.excursion",
    "tray.contamination", "npo.violation", "texture.modification.error",
    "enteral.feed.event", "food.recall.applicable",
  ]),
  patientId: z.string().optional(),
  mealId: z.string().optional(),
  dietOrderId: z.string().optional(),
  severity: z.enum(["low", "medium", "high", "critical"]).default("low"),
  payload: z.record(z.unknown()).default({}),
});

const DietaryComplianceSchema = z.object({
  tenantId: z.string().uuid(),
  facilityId: z.string().uuid(),
  patientId: z.string().uuid(),
  dietOrderId: z.string().uuid(),
  violations: z.array(z.object({
    ruleCode: z.string(),
    description: z.string(),
    severity: z.enum(["low", "medium", "high", "critical"]),
    detectedAt: z.string().datetime(),
  })),
  auditedBy: z.string(),
});

export async function registerRoutes(app: FastifyInstance) {
  const nats = (app as any).nats;

  // POST /adapter/healthcare/food-events
  app.post("/adapter/healthcare/food-events", async (req, reply) => {
    const parsed = FoodServiceEventSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { tenantId, facilityId, patientUnitId, eventType, patientId, mealId, dietOrderId, severity, payload } = parsed.data;
    const eventId = randomUUID();

    const isHighRisk =
      eventType.includes("allergen") || eventType.includes("npo") ||
      eventType.includes("contamination") || eventType.includes("recall") ||
      severity === "critical" || severity === "high";

    const envelope = {
      id: eventId,
      tenantId,
      entityType: "meal",
      entityId: mealId ?? eventId,
      eventType,
      facilityId,
      severity,
      payload: {
        patientUnitId, patientId: patientId ? `[PHI-MASKED]` : null,
        mealId, dietOrderId, adapterSource: "vertical-healthcare", ...payload,
      },
      sourceSystem: "healthcare-adapter",
      ts: new Date().toISOString(),
    };

    // All healthcare food events → provenance (audit trail for Joint Commission)
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify(envelope)));

    // High-risk events → food defense
    if (isHighRisk) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify(envelope)));
    }

    nats.publish("atlas.adapter.healthcare.food-event", Buffer.from(JSON.stringify(envelope)));

    return reply.code(202).send({ id: eventId, severity, highRisk: isHighRisk, accepted: true });
  });

  // POST /adapter/healthcare/dietary-compliance
  app.post("/adapter/healthcare/dietary-compliance", async (req, reply) => {
    const parsed = DietaryComplianceSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { tenantId, facilityId, patientId, dietOrderId, violations, auditedBy } = parsed.data;
    const auditId = randomUUID();

    // Provenance record for the compliance audit
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify({
      id: auditId,
      tenantId,
      entityType: "diet-order",
      entityId: dietOrderId,
      eventType: "dietary.compliance.audit",
      actorId: auditedBy,
      facilityId,
      payload: {
        patientId: `[PHI-MASKED]`, violationCount: violations.length,
        hasCritical: violations.some((v) => v.severity === "critical"),
        adapterSource: "vertical-healthcare",
      },
      sourceSystem: "healthcare-adapter",
      ts: new Date().toISOString(),
    })));

    // Any critical violations → food defense alert
    const criticalViolations = violations.filter((v) => v.severity === "critical" || v.severity === "high");
    if (criticalViolations.length > 0) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify({
        id: randomUUID(),
        tenantId,
        facilityId,
        eventType: "dietary.violation",
        severity: criticalViolations.some((v) => v.severity === "critical") ? "critical" : "high",
        payload: { violationCount: criticalViolations.length, ruleCodes: criticalViolations.map((v) => v.ruleCode) },
        sourceSystem: "healthcare-adapter",
        ts: new Date().toISOString(),
      })));
    }

    return reply.code(202).send({ id: auditId, violationCount: violations.length });
  });

  // POST /adapter/healthcare/recall-screen — screen active patients against a recall
  app.post("/adapter/healthcare/recall-screen", async (req, reply) => {
    const body = req.body as {
      tenantId: string;
      facilityId: string;
      recallId: string;
      affectedProductCodes: string[];
      screenedBy: string;
    };

    const screenId = randomUUID();

    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify({
      id: screenId,
      tenantId: body.tenantId,
      entityType: "recall-screen",
      entityId: body.recallId,
      eventType: "food.recall.screen",
      actorId: body.screenedBy,
      facilityId: body.facilityId,
      payload: {
        recallId: body.recallId,
        affectedProductCodes: body.affectedProductCodes,
        adapterSource: "vertical-healthcare",
      },
      sourceSystem: "healthcare-adapter",
      ts: new Date().toISOString(),
    })));

    nats.publish("atlas.adapter.healthcare.recall-screen", Buffer.from(JSON.stringify({
      screenId, ...body, ts: new Date().toISOString(),
    })));

    return reply.code(202).send({ screenId, status: "screening-initiated" });
  });
}

import Fastify from "fastify";
import { logger } from "./lib/logger";
import { connectNats } from "./lib/nats";
import { registerRoutes } from "./routes";

async function bootstrap() {
  const nats = await connectNats(process.env.NATS_URL ?? "nats://localhost:4222");
  const app = Fastify({ logger: false, trustProxy: true, genReqId: () => crypto.randomUUID() });
  app.decorate("nats", nats);
  await registerRoutes(app);
  app.get("/health", async () => ({ status: "ok", adapter: "vertical-logistics", version: "40.1.0", ts: new Date().toISOString() }));
  const port = parseInt(process.env.PORT ?? "4002", 10);
  await app.listen({ port, host: "0.0.0.0" });
  logger.info({ port }, "Logistics vertical adapter listening");
}
bootstrap().catch((err) => { logger.fatal({ err }, "Fatal startup"); process.exit(1); });

import { connect, type NatsConnection } from "nats";
import { logger } from "./logger";
export async function connectNats(url: string): Promise<NatsConnection> {
  const nc = await connect({ servers: url, maxReconnectAttempts: -1 });
  logger.info({ url }, "NATS connected");
  return nc;
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const ShipmentEventSchema = z.object({
  tenantId: z.string().uuid(),
  shipmentId: z.string().uuid(),
  carrierId: z.string(),
  eventType: z.enum([
    "shipment.created", "shipment.picked-up", "shipment.in-transit",
    "shipment.out-for-delivery", "shipment.delivered", "shipment.exception",
    "shipment.returned", "shipment.lost", "temperature.excursion",
    "chain-of-custody.break", "seal.broken", "tamper.detected",
  ]),
  facilityId: z.string().uuid().optional(),
  temperature: z.number().optional(),
  location: z.object({ lat: z.number(), lon: z.number() }).optional(),
  payload: z.record(z.unknown()).default({}),
});

const ChainOfCustodySchema = z.object({
  tenantId: z.string().uuid(),
  shipmentId: z.string().uuid(),
  fromPartyId: z.string().uuid(),
  toPartyId: z.string().uuid(),
  transferType: z.enum(["handoff", "scan", "delivery", "return"]),
  location: z.string().optional(),
  signature: z.string().optional(),
  payload: z.record(z.unknown()).default({}),
});

export async function registerRoutes(app: FastifyInstance) {
  const nats = (app as any).nats;

  // POST /adapter/logistics/shipment-events
  app.post("/adapter/logistics/shipment-events", async (req, reply) => {
    const parsed = ShipmentEventSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { tenantId, shipmentId, carrierId, eventType, facilityId, temperature, location, payload } = parsed.data;
    const eventId = randomUUID();

    const isFoodDefenseEvent =
      eventType.includes("temperature") ||
      eventType.includes("tamper") ||
      eventType.includes("seal") ||
      eventType.includes("chain-of-custody");

    const envelope = {
      id: eventId,
      tenantId,
      entityType: "shipment",
      entityId: shipmentId,
      eventType,
      facilityId: facilityId ?? carrierId,
      severity: isFoodDefenseEvent ? "high" : "low",
      payload: { carrierId, temperature, location, adapterSource: "vertical-logistics", ...payload },
      sourceSystem: "logistics-adapter",
      ts: new Date().toISOString(),
    };

    // Route to food-defense or provenance based on event type
    if (isFoodDefenseEvent) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify(envelope)));
    }
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify(envelope)));
    nats.publish("atlas.adapter.logistics.shipment-event", Buffer.from(JSON.stringify(envelope)));

    return reply.code(202).send({ id: eventId, accepted: true });
  });

  // POST /adapter/logistics/chain-of-custody
  app.post("/adapter/logistics/chain-of-custody", async (req, reply) => {
    const parsed = ChainOfCustodySchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { tenantId, shipmentId, fromPartyId, toPartyId, transferType, location, signature, payload } = parsed.data;
    const transferId = randomUUID();

    const envelope = {
      id: transferId,
      tenantId,
      entityType: "shipment",
      entityId: shipmentId,
      eventType: `chain-of-custody.${transferType}`,
      actorId: fromPartyId,
      payload: { fromPartyId, toPartyId, location, signature: signature ? "[PRESENT]" : null, ...payload },
      sourceSystem: "logistics-adapter",
      ts: new Date().toISOString(),
    };

    // Chain of custody is always a provenance event
    nats.publish("atlas.provenance.record.created", Buffer.from(JSON.stringify(envelope)));

    // If no signature, flag as a chain break
    if (!signature) {
      nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify({
        ...envelope,
        facilityId: fromPartyId,
        eventType: "chain-of-custody.break",
        severity: "high",
      })));
    }

    return reply.code(202).send({ id: transferId, accepted: true });
  });

  // POST /adapter/logistics/temperature-telemetry — bulk IoT sensor ingest
  app.post("/adapter/logistics/temperature-telemetry", async (req, reply) => {
    const readings = (req.body as { readings: unknown[] })?.readings ?? [];
    if (!Array.isArray(readings) || readings.length === 0) {
      return reply.code(400).send({ error: "readings array required" });
    }

    const TelemetrySchema = z.object({
      tenantId: z.string().uuid(),
      shipmentId: z.string().uuid(),
      sensorId: z.string(),
      temperature: z.number(),
      humidity: z.number().optional(),
      ts: z.string().datetime(),
      minThreshold: z.number().optional(),
      maxThreshold: z.number().optional(),
    });

    let accepted = 0;
    const batchId = randomUUID();

    for (const reading of readings.slice(0, 5000)) {
      try {
        const r = TelemetrySchema.parse(reading);
        const isExcursion =
          (r.minThreshold != null && r.temperature < r.minThreshold) ||
          (r.maxThreshold != null && r.temperature > r.maxThreshold);

        if (isExcursion) {
          nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify({
            id: randomUUID(),
            tenantId: r.tenantId,
            facilityId: r.shipmentId,
            entityType: "shipment",
            entityId: r.shipmentId,
            eventType: "temperature.excursion",
            severity: Math.abs(r.temperature - (r.maxThreshold ?? r.minThreshold ?? 0)) > 10 ? "high" : "medium",
            payload: { sensorId: r.sensorId, temperature: r.temperature, humidity: r.humidity, batchId, ...r },
            sourceSystem: "logistics-adapter-telemetry",
            ts: r.ts,
          })));
        }

        accepted++;
      } catch { /* skip invalid */ }
    }

    return reply.code(202).send({ batchId, accepted, total: readings.length });
  });
}

import Fastify from "fastify";
import { z } from "zod";
import { logger } from "./lib/logger";
import { connectNats } from "./lib/nats";
import { registerRoutes } from "./routes";

async function bootstrap() {
  const nats = await connectNats(process.env.NATS_URL ?? "nats://localhost:4222");

  const app = Fastify({ logger: false, trustProxy: true, genReqId: () => crypto.randomUUID() });
  app.decorate("nats", nats);

  await registerRoutes(app);

  app.get("/health", async () => ({
    status: "ok", adapter: "vertical-retail", version: "40.1.0",
    ts: new Date().toISOString(),
  }));

  const port = parseInt(process.env.PORT ?? "4001", 10);
  await app.listen({ port, host: "0.0.0.0" });
  logger.info({ port }, "Retail vertical adapter listening");
}

bootstrap().catch((err) => { logger.fatal({ err }, "Fatal startup"); process.exit(1); });

import { connect, type NatsConnection } from "nats";
import { logger } from "./logger";
export async function connectNats(url: string): Promise<NatsConnection> {
  const nc = await connect({ servers: url, maxReconnectAttempts: -1 });
  logger.info({ url }, "NATS connected");
  return nc;
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const ProductEventSchema = z.object({
  tenantId: z.string().uuid(),
  storeId: z.string().uuid(),
  productId: z.string().uuid(),
  sku: z.string(),
  eventType: z.enum([
    "product.received", "product.shelved", "product.sold",
    "product.returned", "product.recalled", "product.damaged",
    "product.expired", "inventory.adjustment", "temperature.excursion",
  ]),
  quantity: z.number().optional(),
  batchCode: z.string().optional(),
  payload: z.record(z.unknown()).default({}),
});

const InventoryQuerySchema = z.object({
  tenantId: z.string().uuid(),
  storeId: z.string().uuid().optional(),
  sku: z.string().optional(),
});

export async function registerRoutes(app: FastifyInstance) {
  const nats = (app as any).nats;

  // POST /adapter/retail/product-events — ingest POS / WMS events
  app.post("/adapter/retail/product-events", async (req, reply) => {
    const parsed = ProductEventSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { tenantId, storeId, productId, sku, eventType, quantity, batchCode, payload } = parsed.data;
    const eventId = randomUUID();

    // Map retail events to Atlas One canonical events
    const canonicalSubject = eventType.startsWith("temperature")
      ? "atlas.food-defense.event.ingest"
      : "atlas.provenance.record.created";

    const envelope = {
      id: eventId,
      tenantId,
      entityType: "product",
      entityId: productId,
      eventType,
      facilityId: storeId,
      severity: eventType.includes("recall") || eventType.includes("expired") ? "high" : "low",
      payload: {
        storeId, sku, quantity, batchCode,
        adapterSource: "vertical-retail",
        ...payload,
      },
      sourceSystem: "retail-adapter",
      ts: new Date().toISOString(),
    };

    nats.publish(canonicalSubject, Buffer.from(JSON.stringify(envelope)));

    // Also publish to adapter-specific subject for any retail-specific consumers
    nats.publish("atlas.adapter.retail.product-event",
      Buffer.from(JSON.stringify(envelope)));

    return reply.code(202).send({ id: eventId, accepted: true });
  });

  // POST /adapter/retail/recall — trigger a product recall workflow
  app.post("/adapter/retail/recall", async (req, reply) => {
    const body = req.body as {
      tenantId: string;
      productId: string;
      sku: string;
      reason: string;
      severity: "class-i" | "class-ii" | "class-iii";
      affectedStoreIds?: string[];
      batchCodes?: string[];
    };

    const recallId = randomUUID();

    // Publish high-severity food defense event
    nats.publish("atlas.food-defense.event.ingest", Buffer.from(JSON.stringify({
      id: randomUUID(),
      tenantId: body.tenantId,
      facilityId: body.affectedStoreIds?.[0] ?? "all-stores",
      eventType: "recall.trigger",
      severity: "critical",
      payload: {
        recallId, productId: body.productId, sku: body.sku,
        reason: body.reason, severity: body.severity,
        affectedStoreIds: body.affectedStoreIds,
        batchCodes: body.batchCodes,
        adapterSource: "vertical-retail",
      },
      sourceSystem: "retail-adapter",
    })));

    // Publish recall coordination event
    nats.publish("atlas.adapter.retail.recall.initiated", Buffer.from(JSON.stringify({
      recallId, tenantId: body.tenantId, productId: body.productId,
      sku: body.sku, severity: body.severity, initiatedAt: new Date().toISOString(),
    })));

    return reply.code(202).send({ recallId, status: "initiated" });
  });

  // POST /adapter/retail/inventory-sync — bulk inventory sync from WMS
  app.post("/adapter/retail/inventory-sync", async (req, reply) => {
    const items = (req.body as { items: unknown[] })?.items ?? [];
    if (!Array.isArray(items) || items.length === 0) {
      return reply.code(400).send({ error: "items array required" });
    }

    const batchId = randomUUID();
    let accepted = 0;

    for (const item of items.slice(0, 1000)) {
      try {
        const parsed = ProductEventSchema.safeParse({ ...(item as object), eventType: "inventory.adjustment" });
        if (parsed.success) {
          nats.publish("atlas.adapter.retail.inventory-sync",
            Buffer.from(JSON.stringify({ ...parsed.data, batchId })));
          accepted++;
        }
      } catch { /* skip invalid items */ }
    }

    return reply.code(202).send({ batchId, accepted, total: items.length });
  });
}

import type { AtlasClientOptions, TokenProvider, RequestOptions } from "./types";
import { AtlasApiError, AtlasAuthError, AtlasNetworkError } from "./errors";

export class AtlasOneClient {
  protected baseUrl: string;
  protected tenantId: string;
  protected tokenProvider: TokenProvider;
  protected defaultHeaders: Record<string, string>;

  constructor(options: AtlasClientOptions) {
    this.baseUrl   = options.baseUrl.replace(/\/$/, "");
    this.tenantId  = options.tenantId;
    this.tokenProvider = options.tokenProvider;
    this.defaultHeaders = {
      "Content-Type": "application/json",
      "X-Tenant-ID":  options.tenantId,
      "User-Agent":   "atlas-one-sdk-node/40.1.0",
      ...(options.extraHeaders ?? {}),
    };
  }

  protected async request<T>(
    method: string,
    path: string,
    body?: unknown,
    options?: RequestOptions
  ): Promise<T> {
    const token = await this.tokenProvider.getToken();
    const url = `${this.baseUrl}${path}`;

    let res: Response;
    try {
      res = await fetch(url, {
        method,
        headers: {
          ...this.defaultHeaders,
          Authorization: `Bearer ${token}`,
          ...(options?.headers ?? {}),
        },
        body: body != null ? JSON.stringify(body) : undefined,
        signal: AbortSignal.timeout(options?.timeoutMs ?? 30_000),
      });
    } catch (err: any) {
      throw new AtlasNetworkError(`Network request failed: ${err.message}`, err);
    }

    if (res.status === 401) {
      const detail = await res.json().catch(() => ({}));
      throw new AtlasAuthError(detail.error ?? "Authentication failed", res.status, detail.code);
    }

    if (!res.ok) {
      const detail = await res.json().catch(() => ({}));
      throw new AtlasApiError(
        detail.error ?? `HTTP ${res.status}`,
        res.status,
        detail.code,
        detail
      );
    }

    if (res.status === 204) return undefined as T;
    return res.json() as Promise<T>;
  }

  get<T>(path: string, opts?: RequestOptions)                     { return this.request<T>("GET",    path, undefined, opts); }
  post<T>(path: string, body?: unknown, opts?: RequestOptions)    { return this.request<T>("POST",   path, body, opts); }
  put<T>(path: string, body?: unknown, opts?: RequestOptions)     { return this.request<T>("PUT",    path, body, opts); }
  patch<T>(path: string, body?: unknown, opts?: RequestOptions)   { return this.request<T>("PATCH",  path, body, opts); }
  delete<T>(path: string, opts?: RequestOptions)                  { return this.request<T>("DELETE", path, undefined, opts); }
}

