from __future__ import annotations

import json
from typing import Any, Dict, Optional
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode

from .errors import AtlasApiError, AtlasAuthError, AtlasNetworkError
from .types import ClientOptions


class AtlasOneClient:
    """Base HTTP client for Atlas One API."""

    SDK_VERSION = "40.1.0"

    def __init__(self, options: ClientOptions) -> None:
        self.base_url = options.base_url.rstrip("/")
        self.tenant_id = options.tenant_id
        self._token_provider = options.token_provider
        self._extra_headers: Dict[str, str] = options.extra_headers or {}
        self.timeout: int = options.timeout_secs or 30

    def _get_token(self) -> str:
        return self._token_provider.get_token()

    def _build_headers(self, extra: Optional[Dict[str, str]] = None) -> Dict[str, str]:
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "X-Tenant-ID": self.tenant_id,
            "Authorization": f"Bearer {self._get_token()}",
            "User-Agent": f"atlas-one-sdk-python/{self.SDK_VERSION}",
            **self._extra_headers,
            **(extra or {}),
        }
        return headers

    def _request(
        self,
        method: str,
        path: str,
        body: Optional[Any] = None,
        params: Optional[Dict[str, str]] = None,
    ) -> Any:
        url = f"{self.base_url}{path}"
        if params:
            url = f"{url}?{urlencode(params)}"

        data: Optional[bytes] = None
        if body is not None:
            data = json.dumps(body).encode("utf-8")

        req = Request(url, data=data, method=method, headers=self._build_headers())

        try:
            with urlopen(req, timeout=self.timeout) as resp:
                raw = resp.read()
                if not raw:
                    return None
                return json.loads(raw)
        except HTTPError as e:
            raw = e.read()
            try:
                detail = json.loads(raw)
            except Exception:
                detail = {"error": str(e)}
            if e.code == 401:
                raise AtlasAuthError(detail.get("error", "Unauthorized"), e.code, detail.get("code")) from e
            raise AtlasApiError(detail.get("error", f"HTTP {e.code}"), e.code, detail.get("code"), detail) from e
        except URLError as e:
            raise AtlasNetworkError(f"Network error: {e.reason}") from e

    def get(self, path: str, params: Optional[Dict[str, str]] = None) -> Any:
        return self._request("GET", path, params=params)

    def post(self, path: str, body: Optional[Any] = None) -> Any:
        return self._request("POST", path, body=body)

    def put(self, path: str, body: Optional[Any] = None) -> Any:
        return self._request("PUT", path, body=body)

    def patch(self, path: str, body: Optional[Any] = None) -> Any:
        return self._request("PATCH", path, body=body)

    def delete(self, path: str) -> Any:
        return self._request("DELETE", path)

