import Fastify from "fastify";
import { registerPlugins } from "./plugins";
import { registerRoutes } from "./routes";
import { logger } from "./lib/logger";
import { config } from "./lib/config";
import { initTelemetry } from "./lib/telemetry";

async function bootstrap() {
  await initTelemetry("atlas-one-api-gateway");

  const app = Fastify({
    logger: false, // Pino configured separately
    trustProxy: true,
    requestIdHeader: "x-request-id",
    genReqId: () => crypto.randomUUID(),
  });

  await registerPlugins(app);
  await registerRoutes(app);

  app.addHook("onRequest", (req, _reply, done) => {
    logger.info({ reqId: req.id, method: req.method, url: req.url }, "→ request");
    done();
  });

  app.addHook("onResponse", (req, reply, done) => {
    logger.info(
      { reqId: req.id, statusCode: reply.statusCode, responseTime: reply.elapsedTime },
      "← response"
    );
    done();
  });

  app.setErrorHandler((err, req, reply) => {
    logger.error({ err, reqId: req.id }, "Unhandled error");
    reply.status(err.statusCode ?? 500).send({
      error: err.message ?? "Internal Server Error",
      code: err.code ?? "INTERNAL_ERROR",
      reqId: req.id,
    });
  });

  app.get("/health", async () => ({
    status: "ok",
    service: "api-gateway",
    version: "40.1.0",
    ts: new Date().toISOString(),
  }));

  await app.listen({ port: config.PORT, host: "0.0.0.0" });
  logger.info({ port: config.PORT }, "Atlas One API Gateway listening");
}

bootstrap().catch((err) => {
  logger.fatal({ err }, "Fatal startup error");
  process.exit(1);
});

import { z } from "zod";

const ConfigSchema = z.object({
  NODE_ENV: z.enum(["development", "test", "staging", "production"]).default("development"),
  PORT: z.coerce.number().default(3000),
  IDENTITY_SERVICE_URL: z.string().url(),
  PROVENANCE_SERVICE_URL: z.string().url(),
  FOOD_DEFENSE_SERVICE_URL: z.string().url(),
  CONFIG_SERVICE_URL: z.string().url(),
  REDIS_URL: z.string().url(),
  JWT_PUBLIC_KEY_URL: z.string().url(),
  RATE_LIMIT_MAX: z.coerce.number().default(500),
  RATE_LIMIT_WINDOW_MS: z.coerce.number().default(60000),
  CORS_ORIGINS: z.string().default("*"),
  REQUEST_TIMEOUT_MS: z.coerce.number().default(30000),
});

function loadConfig() {
  const result = ConfigSchema.safeParse(process.env);
  if (!result.success) {
    console.error("Invalid configuration:", result.error.flatten());
    process.exit(1);
  }
  return result.data;
}

