import { Resource } from "@opentelemetry/resources";
import { SEMRESATTRS_SERVICE_NAME, SEMRESATTRS_SERVICE_VERSION } from "@opentelemetry/semantic-conventions";

let sdk: NodeSDK | null = null;

export async function initTelemetry(serviceName: string) {
  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT;
  if (!endpoint) return;

  sdk = new NodeSDK({
    resource: new Resource({
      [SEMRESATTRS_SERVICE_NAME]: serviceName,
      [SEMRESATTRS_SERVICE_VERSION]: "40.1.0",
      "deployment.environment": process.env.NODE_ENV ?? "development",
    }),
    traceExporter: new OTLPTraceExporter({ url: `${endpoint}/v1/traces` }),
  });

  sdk.start();

  process.on("SIGTERM", async () => {
    await sdk?.shutdown();
  });
}

import type { FastifyRequest, FastifyReply } from "fastify";
import { createRemoteJWKSet, jwtVerify } from "jose";
import { config } from "../lib/config";
import { logger } from "../lib/logger";

let jwks: ReturnType<typeof createRemoteJWKSet>;

function getJwks() {
  if (!jwks) {
    jwks = createRemoteJWKSet(new URL(config.JWT_PUBLIC_KEY_URL), {
      cacheMaxAge: 600_000, // 10 min
    });
  }
  return jwks;
}

export interface JwtPayload {
  sub: string;
  tenantId: string;
  roles: string[];
  permissions: string[];
  sessionId: string;
  iat: number;
  exp: number;
  iss: string;
  aud: string | string[];
}

declare module "fastify" {
  interface FastifyRequest {
    principal?: JwtPayload;
  }
}

export async function authenticate(req: FastifyRequest, reply: FastifyReply) {
  const header = req.headers.authorization;
  if (!header || !header.startsWith("Bearer ")) {
    reply.code(401).send({ error: "Missing or malformed Authorization header", code: "UNAUTHORIZED" });
    return;
  }

  const token = header.slice(7);
  try {
    const { payload } = await jwtVerify(token, getJwks(), {
      issuer: process.env.JWT_ISSUER,
      audience: "atlas-one",
    });
    req.principal = payload as unknown as JwtPayload;
  } catch (err) {
    logger.warn({ err, reqId: req.id }, "JWT verification failed");
    reply.code(401).send({ error: "Invalid or expired token", code: "TOKEN_INVALID" });
  }
}

export function requireRoles(...roles: string[]) {
  return async (req: FastifyRequest, reply: FastifyReply) => {
    const principal = req.principal;
    if (!principal) {
      reply.code(401).send({ error: "Not authenticated", code: "UNAUTHORIZED" });
      return;
    }
    const hasRole = roles.some((r) => principal.roles.includes(r));
    if (!hasRole) {
      logger.warn({ sub: principal.sub, required: roles, actual: principal.roles }, "Insufficient roles");
      reply.code(403).send({ error: "Insufficient permissions", code: "FORBIDDEN", required: roles });
    }
  };
}

export function requirePermissions(...perms: string[]) {
  return async (req: FastifyRequest, reply: FastifyReply) => {
    const principal = req.principal;
    if (!principal) {
      reply.code(401).send({ error: "Not authenticated", code: "UNAUTHORIZED" });
      return;
    }
    const missing = perms.filter((p) => !principal.permissions.includes(p));
    if (missing.length > 0) {
      logger.warn({ sub: principal.sub, missing }, "Missing permissions");
      reply.code(403).send({ error: "Insufficient permissions", code: "FORBIDDEN", missing });
    }
  };
}

import type { FastifyRequest, FastifyReply } from "fastify";
import { logger } from "../lib/logger";

export async function tenantMiddleware(req: FastifyRequest, reply: FastifyReply) {
  const tenantId =
    (req.headers["x-tenant-id"] as string) ??
    req.principal?.tenantId;

  if (!tenantId) {
    reply.code(400).send({ error: "Missing X-Tenant-ID header", code: "TENANT_REQUIRED" });
    return;
  }

  // Ensure the JWT's tenant matches the header (prevent cross-tenant spoofing)
  if (req.principal && req.principal.tenantId !== tenantId) {
    logger.warn(
      { sub: req.principal.sub, jwtTenant: req.principal.tenantId, headerTenant: tenantId },
      "Tenant mismatch — possible spoofing attempt"
    );
    reply.code(403).send({ error: "Tenant mismatch", code: "TENANT_MISMATCH" });
    return;
  }

  // Attach to request for downstream use
  (req as any).tenantId = tenantId;
}

import type { FastifyRequest, FastifyReply } from "fastify";
import { trace, context, propagation, SpanStatusCode } from "@opentelemetry/api";

export async function traceMiddleware(req: FastifyRequest, _reply: FastifyReply, done: () => void) {
  const tracer = trace.getTracer("atlas-one-api-gateway", "40.1.0");
  const ctx = propagation.extract(context.active(), req.headers as Record<string, string>);

  const span = tracer.startSpan(`${req.method} ${req.routerPath ?? req.url}`, undefined, ctx);
  span.setAttributes({
    "http.method": req.method,
    "http.url": req.url,
    "http.request_id": req.id as string,
    "net.peer.ip": req.ip,
    "atlas.tenant_id": (req.headers["x-tenant-id"] as string) ?? "unknown",
  });

  req.raw.on("close", () => {
    span.setStatus({ code: SpanStatusCode.OK });
    span.end();
  });

  done();
}

import type { FastifyInstance } from "fastify";
import cors from "@fastify/cors";
import helmet from "@fastify/helmet";
import rateLimit from "@fastify/rate-limit";
import replyFrom from "@fastify/reply-from";
import { config } from "../lib/config";
import { createRedisClient } from "../lib/redis";

export async function registerPlugins(app: FastifyInstance) {
  // CORS
  await app.register(cors, {
    origin: config.CORS_ORIGINS === "*" ? true : config.CORS_ORIGINS.split(","),
    methods: ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
    allowedHeaders: ["Authorization", "Content-Type", "X-Tenant-ID", "X-Request-ID"],
    credentials: true,
  });

  // Helmet (security headers)
  await app.register(helmet, {
    contentSecurityPolicy: false, // handled by nginx upstream
  });

  // Rate limiting (Redis-backed)
  const redis = createRedisClient();
  await app.register(rateLimit, {
    max: config.RATE_LIMIT_MAX,
    timeWindow: config.RATE_LIMIT_WINDOW_MS,
    redis,
    keyGenerator: (req) => {
      // Key by tenant + IP
      const tenant = req.headers["x-tenant-id"] ?? "anonymous";
      return `rl:${tenant}:${req.ip}`;
    },
    errorResponseBuilder: (_req, context) => ({
      error: "Rate limit exceeded",
      code: "RATE_LIMIT_EXCEEDED",
      limit: context.max,
      resetAt: new Date(Date.now() + context.ttl).toISOString(),
    }),
  });

  // Reverse proxy to upstream services
  await app.register(replyFrom, {
    rewriteRequestHeaders: (req, headers) => ({
      ...headers,
      "x-forwarded-for": req.ip,
      "x-request-id": req.id,
      "x-gateway-version": "40.1.0",
    }),
  });
}

import type { FastifyInstance } from "fastify";
import { config } from "../lib/config";
import { authenticate } from "../middleware/auth";
import { tenantMiddleware } from "../middleware/tenant";
import { traceMiddleware } from "../middleware/trace";

export async function registerRoutes(app: FastifyInstance) {
  // Global hooks
  app.addHook("onRequest", traceMiddleware);

  // ── Public routes ──────────────────────────────────────────────────────
  app.get("/", async () => ({ service: "atlas-one-api-gateway", version: "40.1.0" }));
  app.get("/health", async () => ({ status: "ok", ts: new Date().toISOString() }));
  app.get("/ready", async (_req, reply) => {
    // Shallow upstream ping
    try {
      const res = await fetch(`${config.IDENTITY_SERVICE_URL}/health`, { signal: AbortSignal.timeout(2000) });
      if (!res.ok) throw new Error("identity unhealthy");
      reply.send({ status: "ready" });
    } catch {
      reply.code(503).send({ status: "not ready" });
    }
  });

  // ── Identity proxy ─────────────────────────────────────────────────────
  app.register(async (sub) => {
    sub.post("/auth/login", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/auth/login") });
    sub.post("/auth/refresh", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/auth/refresh") });
    sub.post("/auth/logout", {
      preHandler: [authenticate],
      handler: proxyTo(config.IDENTITY_SERVICE_URL, "/auth/logout"),
    });
    sub.post("/auth/mfa/enroll", {
      preHandler: [authenticate],
      handler: proxyTo(config.IDENTITY_SERVICE_URL, "/auth/mfa/enroll"),
    });
    sub.post("/auth/mfa/verify", {
      preHandler: [authenticate],
      handler: proxyTo(config.IDENTITY_SERVICE_URL, "/auth/mfa/verify"),
    });
    sub.get("/auth/jwks", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/.well-known/jwks.json") });
    sub.get("/auth/openid-configuration", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/.well-known/openid-configuration") });
  });

  // ── Authenticated API routes ───────────────────────────────────────────
  app.register(async (sub) => {
    sub.addHook("preHandler", authenticate);
    sub.addHook("preHandler", tenantMiddleware);

    // Identity management
    sub.register(async (id) => {
      id.get("/users", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/users") });
      id.post("/users", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/users") });
      id.get("/users/:id", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/users/:id") });
      id.patch("/users/:id", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/users/:id") });
      id.delete("/users/:id", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/users/:id") });
      id.get("/tenants", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/tenants") });
      id.post("/tenants", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/tenants") });
      id.get("/roles", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/roles") });
      id.post("/roles", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/roles") });
      id.get("/api-keys", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/api-keys") });
      id.post("/api-keys", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/api-keys") });
      id.delete("/api-keys/:id", { handler: proxyTo(config.IDENTITY_SERVICE_URL, "/api-keys/:id") });
    }, { prefix: "/identity" });

    // Provenance
    sub.register(async (prov) => {
      prov.post("/records", { handler: proxyTo(config.PROVENANCE_SERVICE_URL, "/records") });
      prov.get("/records/:id", { handler: proxyTo(config.PROVENANCE_SERVICE_URL, "/records/:id") });
      prov.get("/records/:id/chain", { handler: proxyTo(config.PROVENANCE_SERVICE_URL, "/records/:id/chain") });
      prov.post("/attestations", { handler: proxyTo(config.PROVENANCE_SERVICE_URL, "/attestations") });
      prov.get("/attestations/:id", { handler: proxyTo(config.PROVENANCE_SERVICE_URL, "/attestations/:id") });
      prov.post("/verify", { handler: proxyTo(config.PROVENANCE_SERVICE_URL, "/verify") });
    }, { prefix: "/provenance" });

    // Food Defense
    sub.register(async (fd) => {
      fd.post("/events", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/events") });
      fd.get("/events", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/events") });
      fd.get("/events/:id", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/events/:id") });
      fd.post("/score", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/score") });
      fd.get("/alerts", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/alerts") });
      fd.patch("/alerts/:id", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/alerts/:id") });
      fd.get("/rules", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/rules") });
      fd.post("/rules", { handler: proxyTo(config.FOOD_DEFENSE_SERVICE_URL, "/rules") });
    }, { prefix: "/food-defense" });

    // Config
    sub.register(async (cfg) => {
      cfg.get("/flags", { handler: proxyTo(config.CONFIG_SERVICE_URL, "/flags") });
      cfg.get("/flags/:key", { handler: proxyTo(config.CONFIG_SERVICE_URL, "/flags/:key") });
      cfg.put("/flags/:key", { handler: proxyTo(config.CONFIG_SERVICE_URL, "/flags/:key") });
    }, { prefix: "/config" });
  }, { prefix: "/api/v1" });
}

function proxyTo(baseUrl: string, path: string) {
  return async function (req: any, reply: any) {
    const upstream = `${baseUrl}${path.replace(/:(\w+)/g, (_, k) => req.params[k] ?? `:${k}`)}`;
    const qs = new URLSearchParams(req.query as Record<string, string>).toString();
    const url = qs ? `${upstream}?${qs}` : upstream;

    const response = await fetch(url, {
      method: req.method,
      headers: {
        "content-type": "application/json",
        "x-tenant-id": (req.headers["x-tenant-id"] as string) ?? "",
        "x-request-id": req.id as string,
        "x-principal-sub": req.principal?.sub ?? "",
        "x-principal-roles": (req.principal?.roles ?? []).join(","),
      },
      body: ["POST", "PUT", "PATCH"].includes(req.method) ? JSON.stringify(req.body) : undefined,
      signal: AbortSignal.timeout(30_000),
    });

    const body = await response.json();
    reply.code(response.status).send(body);
  };
}

