import type { NatsConnection } from "nats";
import type { Pool } from "pg";
import { StringCodec } from "nats";
import { createHash } from "crypto";
import { logger } from "../lib/logger";
import { randomUUID } from "crypto";

const sc = StringCodec();

export interface AuditEntry {
  id: string;
  tenantId?: string;
  subject: string;
  payload: Record<string, unknown>;
  previousHash: string | null;
  hash: string;
  sequenceNumber: number;
  createdAt: Date;
}

async function getLastEntry(db: Pool): Promise<{ hash: string; sequenceNumber: number } | null> {
  const result = await db.query(
    `SELECT hash, sequence_number FROM audit_log ORDER BY sequence_number DESC LIMIT 1`
  );
  if (result.rowCount === 0) return null;
  return { hash: result.rows[0].hash, sequenceNumber: result.rows[0].sequence_number };
}

function computeAuditHash(
  id: string,
  subject: string,
  payload: Record<string, unknown>,
  previousHash: string | null,
  sequenceNumber: number
): string {
  const canonical = JSON.stringify({ id, subject, payload, previousHash, sequenceNumber });
  return createHash("sha256").update(canonical).digest("hex");
}

export async function startAuditConsumer(nats: NatsConnection, db: Pool) {
  logger.info("Audit log consumer started — subscribing to atlas.>");

  const sub = nats.subscribe("atlas.>", { queue: "audit-logger" });

  (async () => {
    for await (const msg of sub) {
      try {
        const subject = msg.subject;
        let payload: Record<string, unknown> = {};
        try {
          payload = JSON.parse(sc.decode(msg.data));
        } catch {
          payload = { raw: sc.decode(msg.data) };
        }

        const tenantId = (payload.tenantId as string) ?? null;
        const entryId  = randomUUID();

        const client = await db.connect();
        try {
          await client.query("BEGIN");
          await client.query(`SELECT pg_advisory_xact_lock(hashtext('audit_log_chain'))`);

          const last = await getLastEntry(db);
          const previousHash   = last?.hash ?? null;
          const sequenceNumber = (last?.sequenceNumber ?? -1) + 1;
          const hash = computeAuditHash(entryId, subject, payload, previousHash, sequenceNumber);

          await client.query(
            `INSERT INTO audit_log
               (id, tenant_id, subject, payload, previous_hash, hash, sequence_number)
             VALUES ($1,$2,$3,$4,$5,$6,$7)`,
            [entryId, tenantId, subject, JSON.stringify(payload), previousHash, hash, sequenceNumber]
          );

          await client.query("COMMIT");
        } catch (err) {
          await client.query("ROLLBACK");
          throw err;
        } finally {
          client.release();
        }
      } catch (err) {
        logger.error({ err, subject: msg.subject }, "Audit consumer error");
      }
    }
  })();
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { createHash } from "crypto";

export async function registerRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  // GET /logs — paginated audit trail
  app.get("/logs", async (req, reply) => {
    const tenantId = req.headers["x-tenant-id"] as string;
    const { page = "1", limit = "100", subject } = req.query as Record<string, string>;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    const filters = ["1=1"];
    const params: unknown[] = [];

    if (tenantId) { params.push(tenantId); filters.push(`tenant_id = $${params.length}`); }
    if (subject)  { params.push(`${subject}%`); filters.push(`subject LIKE $${params.length}`); }

    params.push(parseInt(limit), offset);

    const result = await db.query(
      `SELECT id, tenant_id, subject, previous_hash, hash, sequence_number, created_at
       FROM audit_log
       WHERE ${filters.join(" AND ")}
       ORDER BY sequence_number DESC
       LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params
    );
    return reply.send({ data: result.rows });
  });

  // GET /logs/:id — single audit entry with payload
  app.get("/logs/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const result = await db.query(`SELECT * FROM audit_log WHERE id = $1`, [id]);
    if (result.rowCount === 0) return reply.code(404).send({ error: "Audit entry not found" });
    return reply.send(result.rows[0]);
  });

  // POST /logs/verify — verify tamper-evidence of a range
  app.post("/logs/verify", async (req, reply) => {
    const { fromSeq = 0, toSeq } = (req.body as any) ?? {};
    const result = await db.query(
      `SELECT id, subject, payload, previous_hash, hash, sequence_number
       FROM audit_log
       WHERE sequence_number >= $1 ${toSeq != null ? "AND sequence_number <= $2" : ""}
       ORDER BY sequence_number ASC`,
      toSeq != null ? [fromSeq, toSeq] : [fromSeq]
    );

    const entries = result.rows;
    let previousHash: string | null = entries[0]?.previous_hash ?? null;
    let valid = true;
    let brokenAt: number | null = null;

    for (const entry of entries) {
      if (entry.previous_hash !== previousHash) {
        valid = false;
        brokenAt = entry.sequence_number;
        break;
      }
      const expected = createHash("sha256")
        .update(JSON.stringify({ id: entry.id, subject: entry.subject, payload: entry.payload, previousHash: entry.previous_hash, sequenceNumber: entry.sequence_number }))
        .digest("hex");
      if (expected !== entry.hash) {
        valid = false;
        brokenAt = entry.sequence_number;
        break;
      }
      previousHash = entry.hash;
    }

    return reply.send({
      valid,
      brokenAt,
      checkedEntries: entries.length,
      fromSeq,
      toSeq: toSeq ?? entries[entries.length - 1]?.sequence_number,
      verifiedAt: new Date().toISOString(),
    });
  });
}

