import type { Pool } from "pg";
import type Redis from "ioredis";
import type { NatsConnection } from "nats";
import { StringCodec } from "nats";
import { logger } from "../lib/logger";

const sc = StringCodec();

/**
 * Hot-reload publisher: subscribes to config change events and
 * broadcasts invalidation signals to all services via NATS.
 */
export function startHotReloadPublisher(db: Pool, redis: Redis, nats: NatsConnection) {
  logger.info("Config hot-reload publisher started");

  const sub = nats.subscribe("atlas.config.flag.updated", { queue: "config-hot-reload" });

  (async () => {
    for await (const msg of sub) {
      try {
        const event = JSON.parse(sc.decode(msg.data)) as {
          key: string;
          value: unknown;
          tenantId: string | null;
          environment: string;
          ts: string;
        };

        // Broadcast invalidation to all service namespaces
        const invalidateMsg = Buffer.from(JSON.stringify({
          type: "config.invalidate",
          key: event.key,
          tenantId: event.tenantId,
          environment: event.environment,
          ts: new Date().toISOString(),
        }));

        nats.publish("atlas.config.invalidate", invalidateMsg);
        nats.publish(`atlas.config.invalidate.${event.key}`, invalidateMsg);

        logger.info({ key: event.key, tenantId: event.tenantId }, "Config hot-reload broadcast sent");
      } catch (err) {
        logger.error({ err }, "Hot-reload publisher error");
      }
    }
  })();
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const UpsertFlagSchema = z.object({
  value: z.union([z.boolean(), z.string(), z.number(), z.record(z.unknown())]),
  description: z.string().max(500).optional(),
  environment: z.enum(["development", "staging", "production", "all"]).default("all"),
  rolloutPercentage: z.number().min(0).max(100).default(100),
});

export async function registerRoutes(app: FastifyInstance) {
  const db    = (app as any).db;
  const redis = (app as any).redis;
  const nats  = (app as any).nats;

  // GET /flags — list all flags for tenant+env
  app.get("/flags", async (req, reply) => {
    const tenantId = req.headers["x-tenant-id"] as string ?? "global";
    const env = (req.query as any).environment ?? "all";

    // Check Redis cache
    const cacheKey = `config:flags:${tenantId}:${env}`;
    const cached = await redis.get(cacheKey);
    if (cached) return reply.send({ data: JSON.parse(cached), cached: true });

    const result = await db.query(
      `SELECT key, value, description, environment, rollout_percentage, updated_at
       FROM config_flags
       WHERE (tenant_id = $1 OR tenant_id IS NULL)
         AND (environment = $2 OR environment = 'all')
       ORDER BY key ASC`,
      [tenantId, env]
    );

    await redis.setex(cacheKey, 30, JSON.stringify(result.rows));
    return reply.send({ data: result.rows, cached: false });
  });

  // GET /flags/:key
  app.get("/flags/:key", async (req, reply) => {
    const { key } = req.params as { key: string };
    const tenantId = req.headers["x-tenant-id"] as string ?? "global";

    const cacheKey = `config:flag:${tenantId}:${key}`;
    const cached = await redis.get(cacheKey);
    if (cached) return reply.send({ ...JSON.parse(cached), cached: true });

    const result = await db.query(
      `SELECT key, value, description, environment, rollout_percentage, updated_at
       FROM config_flags
       WHERE key = $1 AND (tenant_id = $2 OR tenant_id IS NULL)
       LIMIT 1`,
      [key, tenantId]
    );

    if (result.rowCount === 0) return reply.code(404).send({ error: "Flag not found" });

    const flag = result.rows[0];
    await redis.setex(cacheKey, 30, JSON.stringify(flag));
    return reply.send({ ...flag, cached: false });
  });

  // PUT /flags/:key — create or update
  app.put("/flags/:key", async (req, reply) => {
    const { key } = req.params as { key: string };
    const parsed = UpsertFlagSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const tenantId = req.headers["x-tenant-id"] as string ?? null;
    const { value, description, environment, rolloutPercentage } = parsed.data;

    await db.query(
      `INSERT INTO config_flags (id, key, tenant_id, value, description, environment, rollout_percentage)
       VALUES ($1,$2,$3,$4,$5,$6,$7)
       ON CONFLICT (key, COALESCE(tenant_id,'__global__'))
       DO UPDATE SET value=$4, description=$5, environment=$6,
                     rollout_percentage=$7, updated_at=NOW()`,
      [randomUUID(), key, tenantId, JSON.stringify(value), description ?? null, environment, rolloutPercentage]
    );

    // Invalidate cache
    await redis.del(`config:flag:${tenantId ?? "global"}:${key}`);
    await redis.del(`config:flags:${tenantId ?? "global"}:${environment}`);

    // Hot-reload broadcast
    nats.publish("atlas.config.flag.updated",
      Buffer.from(JSON.stringify({ key, value, tenantId, environment, ts: new Date().toISOString() })));

    return reply.send({ ok: true, key, value });
  });

  // DELETE /flags/:key
  app.delete("/flags/:key", async (req, reply) => {
    const { key } = req.params as { key: string };
    const tenantId = req.headers["x-tenant-id"] as string ?? null;
    await db.query(`DELETE FROM config_flags WHERE key=$1 AND (tenant_id=$2 OR tenant_id IS NULL)`, [key, tenantId]);
    await redis.del(`config:flag:${tenantId ?? "global"}:${key}`);
    nats.publish("atlas.config.flag.deleted", Buffer.from(JSON.stringify({ key, tenantId, ts: new Date().toISOString() })));
    return reply.send({ ok: true });
  });
}

