import type { NatsConnection } from "nats";
import type Redis from "ioredis";
import { AckPolicy, DeliverPolicy, RetentionPolicy, StorageType, connect } from "nats";
import { config } from "../lib/config";
import { logger } from "../lib/logger";

export const ATLAS_SUBJECTS = [
  "atlas.identity.>",
  "atlas.provenance.>",
  "atlas.food-defense.>",
  "atlas.audit.>",
  "atlas.config.>",
  "atlas.adapter.>",
];

export async function startConsumerGroups(nats: NatsConnection, redis: Redis) {
  const js = nats.jetstream();
  const jsm = await nats.jetstreamManager();

  // Ensure the main stream exists
  try {
    await jsm.streams.add({
      name: config.STREAM_NAME,
      subjects: ATLAS_SUBJECTS,
      retention: RetentionPolicy.Limits,
      storage: StorageType.File,
      max_age: config.RETENTION_HOURS * 3_600_000_000_000, // nanoseconds
      num_replicas: 1,
      deny_delete: false,
      deny_purge: false,
    });
    logger.info({ stream: config.STREAM_NAME }, "JetStream stream created");
  } catch (err: any) {
    if (err.message?.includes("stream name already in use")) {
      logger.info({ stream: config.STREAM_NAME }, "JetStream stream already exists");
    } else {
      throw err;
    }
  }

  // Ensure DLQ stream
  try {
    await jsm.streams.add({
      name: "ATLAS_DLQ",
      subjects: [config.DEAD_LETTER_SUBJECT],
      retention: RetentionPolicy.Limits,
      storage: StorageType.File,
      max_age: 30 * 24 * 3_600_000_000_000,
      num_replicas: 1,
    });
    logger.info("DLQ stream created");
  } catch (err: any) {
    if (!err.message?.includes("stream name already in use")) throw err;
  }

  // Consumer group definitions
  const consumers = [
    { name: "audit-logger",      filterSubject: "atlas.>" },
    { name: "food-defense",      filterSubject: "atlas.provenance.>" },
    { name: "provenance-anchor", filterSubject: "atlas.provenance.record.created" },
  ];

  for (const consumer of consumers) {
    try {
      await jsm.consumers.add(config.STREAM_NAME, {
        durable_name: consumer.name,
        filter_subject: consumer.filterSubject,
        ack_policy: AckPolicy.Explicit,
        deliver_policy: DeliverPolicy.New,
        ack_wait: config.ACK_WAIT_SECS * 1_000_000_000,
        max_deliver: config.MAX_REDELIVERY,
      });
      logger.info({ consumer: consumer.name }, "Consumer group registered");
    } catch (err: any) {
      if (!err.message?.includes("consumer name already in use")) {
        logger.warn({ err, consumer: consumer.name }, "Consumer group setup warning");
      }
    }
  }

  logger.info("Event mesh consumer groups initialized");
}

import type { NatsConnection } from "nats";
import type Redis from "ioredis";
import { StringCodec } from "nats";
import { config } from "../lib/config";
import { logger } from "../lib/logger";

const sc = StringCodec();
const DLQ_RETRY_KEY = "event-mesh:dlq:retry-count";

export function startDeadLetterProcessor(nats: NatsConnection, redis: Redis) {
  logger.info("Dead-letter processor started");

  const sub = nats.subscribe(config.DEAD_LETTER_SUBJECT, { queue: "dlq-processor" });

  (async () => {
    for await (const msg of sub) {
      try {
        const raw = sc.decode(msg.data);
        const event = JSON.parse(raw) as {
          subject: string;
          payload: unknown;
          error: string;
          retries: number;
          originalTs: string;
          tenantId?: string;
        };

        const retryKey = `${DLQ_RETRY_KEY}:${msg.subject}`;
        const retries = parseInt((await redis.get(retryKey)) ?? "0", 10);

        if (retries < config.MAX_REDELIVERY) {
          // Back-off: 2^retries seconds (1, 2, 4, 8, 16 …)
          const delayMs = Math.pow(2, retries) * 1000;
          await new Promise((r) => setTimeout(r, delayMs));

          nats.publish(event.subject, Buffer.from(JSON.stringify(event.payload)));
          await redis.multi().incr(retryKey).expire(retryKey, 86400).exec();

          logger.info(
            { subject: event.subject, attempt: retries + 1 },
            "DLQ message requeued"
          );
        } else {
          // Permanently failed — store in Redis for inspection / alerting
          const deadKey = `event-mesh:dead:${Date.now()}:${crypto.randomUUID()}`;
          await redis.setex(deadKey, 30 * 86400, raw); // keep 30 days
          await redis.del(retryKey);

          logger.error(
            { subject: event.subject, deadKey, error: event.error },
            "DLQ message permanently failed — archived"
          );

          // Emit monitoring event
          nats.publish(
            "atlas.event-mesh.dead-letter.archived",
            Buffer.from(JSON.stringify({
              deadKey,
              subject: event.subject,
              error: event.error,
              tenantId: event.tenantId,
              ts: new Date().toISOString(),
            }))
          );
        }
      } catch (err) {
        logger.error({ err }, "Dead-letter processor error");
      }
    }
  })();
}

