import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { StringCodec } from "nats";

const sc = StringCodec();

const PublishSchema = z.object({
  subject: z.string().regex(/^atlas\.[a-z0-9._-]+$/).min(5),
  payload: z.record(z.unknown()),
  tenantId: z.string().uuid().optional(),
});

export async function registerRoutes(app: FastifyInstance) {
  const nats  = (app as any).nats;
  const redis = (app as any).redis;

  // POST /publish — programmatic event publish via HTTP
  app.post("/publish", async (req, reply) => {
    const parsed = PublishSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const { subject, payload, tenantId } = parsed.data;
    const envelope = {
      ...payload,
      tenantId: tenantId ?? req.headers["x-tenant-id"],
      publishedAt: new Date().toISOString(),
      publishedBy: req.headers["x-principal-sub"] ?? "api",
      requestId: req.id,
    };

    nats.publish(subject, Buffer.from(JSON.stringify(envelope)));

    return reply.code(202).send({ ok: true, subject, publishedAt: envelope.publishedAt });
  });

  // GET /streams — list JetStream stream info
  app.get("/streams", async (_req, reply) => {
    try {
      const jsm = await nats.jetstreamManager();
      const streams: unknown[] = [];
      const list = await jsm.streams.list();
      for await (const stream of list) {
        streams.push({ name: stream.config.name, subjects: stream.config.subjects, info: stream.state });
      }
      return reply.send({ data: streams });
    } catch {
      return reply.send({ data: [] });
    }
  });

  // GET /status — event mesh status summary
  app.get("/status", async (_req, reply) => {
    const dlqCount = await redis.keys("event-mesh:dead:*").then((k: string[]) => k.length);
    return reply.send({
      status: "ok",
      natsConnected: !nats.isClosed(),
      deadLetterCount: dlqCount,
      ts: new Date().toISOString(),
    });
  });
}

import Fastify from "fastify";
import { config } from "./lib/config";
import { logger } from "./lib/logger";
import { initTelemetry } from "./lib/telemetry";
import { connectDatabase } from "./lib/database";
import { connectNats } from "./lib/nats";
import { connectRedis } from "./lib/redis";
import { registerRoutes } from "./routes";
import { startAnomalyWorker } from "./modules/anomaly-worker";
import { subscribeToEvents } from "./modules/event-consumer";

async function bootstrap() {
  await initTelemetry("atlas-one-food-defense");

  const db    = await connectDatabase(config.DATABASE_URL);
  const nats  = await connectNats(config.NATS_URL);
  const redis = await connectRedis(config.REDIS_URL);

  const app = Fastify({ logger: false, trustProxy: true, genReqId: () => crypto.randomUUID() });

  app.decorate("db", db);
  app.decorate("nats", nats);
  app.decorate("redis", redis);

  await registerRoutes(app);

  app.get("/health", async () => ({
    status: "ok", service: "food-defense", version: "40.1.0",
    ts: new Date().toISOString(),
  }));

  app.setErrorHandler((err, req, reply) => {
    logger.error({ err, reqId: req.id }, "Food-defense unhandled error");
    reply.status(err.statusCode ?? 500).send({ error: err.message ?? "Internal Server Error" });
  });

  // Background workers
  startAnomalyWorker(db, redis, nats, config.ANOMALY_WINDOW_SECS);
  subscribeToEvents(nats, db, redis);

  const graceful = async () => { await app.close(); await nats.drain(); await redis.quit(); process.exit(0); };
  process.on("SIGTERM", graceful);
  process.on("SIGINT", graceful);

  await app.listen({ port: config.PORT, host: "0.0.0.0" });
  logger.info({ port: config.PORT }, "Atlas One Food Defense Service listening");
}

