import type { Pool } from "pg";
import type Redis from "ioredis";
import type { NatsConnection } from "nats";
import { logger } from "../lib/logger";

/**
 * Sliding-window anomaly detector.
 * Scans event counts per (tenant, facility, eventType) in the configured
 * time window and fires alerts when thresholds are breached.
 */
export function startAnomalyWorker(
  db: Pool,
  redis: Redis,
  nats: NatsConnection,
  windowSecs: number
) {
  logger.info({ windowSecs }, "Food-defense anomaly worker started");

  const run = async () => {
    try {
      // Pull distinct tenant/facility pairs with recent events
      const pairs = await db.query<{ tenant_id: string; facility_id: string }>(
        `SELECT DISTINCT tenant_id, facility_id
         FROM food_defense_events
         WHERE created_at > NOW() - ($1 || ' seconds')::interval
           AND anomaly_checked = false`,
        [windowSecs]
      );

      for (const { tenant_id, facility_id } of pairs.rows) {
        // Aggregate event counts in window
        const counts = await db.query<{ event_type: string; cnt: string }>(
          `SELECT event_type, count(*) AS cnt
           FROM food_defense_events
           WHERE tenant_id = $1 AND facility_id = $2
             AND created_at > NOW() - ($3 || ' seconds')::interval
           GROUP BY event_type`,
          [tenant_id, facility_id, windowSecs]
        );

        for (const { event_type, cnt } of counts.rows) {
          const count = parseInt(cnt, 10);

          // Fetch baseline from Redis (set by scoring engine on normal operations)
          const baselineKey = `fd:baseline:${tenant_id}:${facility_id}:${event_type}`;
          const baseline = parseInt((await redis.get(baselineKey)) ?? "5", 10);

          if (count > baseline * 3) {
            // Anomaly: >3x baseline rate
            const alertId = crypto.randomUUID();
            await db.query(
              `INSERT INTO food_defense_alerts
                 (id, tenant_id, facility_id, alert_type, severity, event_type,
                  event_count, baseline, message, status)
               VALUES ($1,$2,$3,'anomaly','high',$4,$5,$6,$7,'open')
               ON CONFLICT DO NOTHING`,
              [
                alertId, tenant_id, facility_id, event_type, count, baseline,
                `Anomaly: ${count} ${event_type} events in ${windowSecs}s window (baseline: ${baseline})`,
              ]
            );

            logger.warn({ tenant_id, facility_id, event_type, count, baseline }, "Anomaly detected");

            nats.publish(
              "atlas.food-defense.anomaly",
              Buffer.from(JSON.stringify({
                alertId, tenantId: tenant_id, facilityId: facility_id,
                eventType: event_type, count, baseline, windowSecs,
                ts: new Date().toISOString(),
              }))
            );
          }
        }

        // Mark events as checked
        await db.query(
          `UPDATE food_defense_events SET anomaly_checked = true
           WHERE tenant_id = $1 AND facility_id = $2
             AND created_at > NOW() - ($3 || ' seconds')::interval`,
          [tenant_id, facility_id, windowSecs]
        );
      }
    } catch (err) {
      logger.error({ err }, "Anomaly worker error");
    }
  };

  run();
  return setInterval(run, windowSecs * 1000);
}

import type { NatsConnection } from "nats";
import type { Pool } from "pg";
import type Redis from "ioredis";
import { StringCodec } from "nats";
import { computeThreatScore, shouldTriggerAlert } from "./scoring-engine";
import { loadActiveRules, evaluateRules } from "./rules-engine";
import { config } from "../lib/config";
import { logger } from "../lib/logger";
import { randomUUID } from "crypto";

const sc = StringCodec();

export function subscribeToEvents(nats: NatsConnection, db: Pool, redis: Redis) {
  // Subscribe to all provenance record events — assess food safety impact
  (async () => {
    const sub = nats.subscribe("atlas.provenance.record.created", {
      queue: "food-defense-assessor",
    });
    for await (const msg of sub) {
      try {
        const data = JSON.parse(sc.decode(msg.data));
        // Only process food-safety relevant entity types
        if (!["batch", "ingredient", "product", "shipment", "facility"].includes(data.entityType)) {
          continue;
        }
        logger.debug({ entityType: data.entityType, entityId: data.entityId }, "Assessing provenance event");
        // Trigger a risk score update for the affected entity
        await redis.setex(
          `fd:entity-risk:${data.tenantId}:${data.entityType}:${data.entityId}`,
          3600,
          JSON.stringify({ assessed: false, ts: new Date().toISOString() })
        );
      } catch (err) {
        logger.error({ err }, "Error processing provenance event");
      }
    }
  })();

  // Subscribe to direct food-defense event ingestion from external systems
  (async () => {
    const sub = nats.subscribe("atlas.food-defense.event.ingest", {
      queue: "food-defense-ingest",
    });
    for await (const msg of sub) {
      try {
        const event = JSON.parse(sc.decode(msg.data));
        const eventId = randomUUID();

        // Persist event
        await db.query(
          `INSERT INTO food_defense_events
             (id, tenant_id, facility_id, event_type, severity, payload, actor_id, source_system)
           VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
          [
            eventId, event.tenantId, event.facilityId, event.eventType,
            event.severity ?? "medium", JSON.stringify(event.payload ?? {}),
            event.actorId ?? "system", event.sourceSystem ?? "event-mesh",
          ]
        );

        // Score the event
        const score = await computeThreatScore(
          { id: eventId, ts: new Date(), ...event },
          db,
          redis
        );

        // Evaluate rules
        const rules = await loadActiveRules(db, event.tenantId, event.eventType);
        const ruleResults = evaluateRules(rules, event.payload ?? {});
        const triggeredRules = ruleResults.filter((r) => r.matched);

        if (shouldTriggerAlert(score, config.THREAT_SCORE_THRESHOLD) || triggeredRules.length > 0) {
          const alertId = randomUUID();
          const maxSeverity =
            score.level === "red" ? "critical"
              : score.level === "orange" ? "high"
              : score.level === "yellow" ? "medium"
              : "low";

          await db.query(
            `INSERT INTO food_defense_alerts
               (id, tenant_id, facility_id, alert_type, severity, event_id,
                threat_score, threat_level, triggered_rules, message, status)
             VALUES ($1,$2,$3,'scored',$4,$5,$6,$7,$8,$9,'open')`,
            [
              alertId, event.tenantId, event.facilityId, maxSeverity, eventId,
              score.score, score.level, JSON.stringify(triggeredRules.map((r) => r.ruleId)),
              score.recommendation,
            ]
          );

          nats.publish(
            "atlas.food-defense.alert.created",
            Buffer.from(JSON.stringify({
              alertId, tenantId: event.tenantId, facilityId: event.facilityId,
              eventId, threatScore: score, triggeredRules, ts: new Date().toISOString(),
            }))
          );

          logger.warn({ alertId, score: score.score, level: score.level }, "Food defense alert created");
        }
      } catch (err) {
        logger.error({ err }, "Error ingesting food defense event");
      }
    }
  })();
}

import type { Pool } from "pg";

export type RuleConditionOperator = "eq" | "neq" | "gt" | "gte" | "lt" | "lte" | "contains" | "in" | "not_in";

export interface RuleCondition {
  field: string;
  operator: RuleConditionOperator;
  value: unknown;
}

export interface DefenseRule {
  id: string;
  tenantId: string;
  name: string;
  description?: string;
  eventTypes: string[];
  conditions: RuleCondition[];
  conditionLogic: "AND" | "OR";
  action: "alert" | "block" | "flag" | "escalate" | "notify";
  priority: number;
  isActive: boolean;
  createdAt: Date;
}

export interface RuleEvalResult {
  ruleId: string;
  ruleName: string;
  matched: boolean;
  action: DefenseRule["action"];
}

function evalCondition(condition: RuleCondition, payload: Record<string, unknown>): boolean {
  const actual = getNestedValue(payload, condition.field);
  switch (condition.operator) {
    case "eq":       return actual === condition.value;
    case "neq":      return actual !== condition.value;
    case "gt":       return typeof actual === "number" && actual > (condition.value as number);
    case "gte":      return typeof actual === "number" && actual >= (condition.value as number);
    case "lt":       return typeof actual === "number" && actual < (condition.value as number);
    case "lte":      return typeof actual === "number" && actual <= (condition.value as number);
    case "contains": return typeof actual === "string" && actual.includes(condition.value as string);
    case "in":       return Array.isArray(condition.value) && (condition.value as unknown[]).includes(actual);
    case "not_in":   return Array.isArray(condition.value) && !(condition.value as unknown[]).includes(actual);
    default:         return false;
  }
}

function getNestedValue(obj: Record<string, unknown>, path: string): unknown {
  return path.split(".").reduce<unknown>((acc, key) => {
    if (acc && typeof acc === "object") return (acc as Record<string, unknown>)[key];
    return undefined;
  }, obj);
}

export async function loadActiveRules(
  db: Pool,
  tenantId: string,
  eventType: string
): Promise<DefenseRule[]> {
  const result = await db.query<DefenseRule>(
    `SELECT * FROM food_defense_rules
     WHERE tenant_id = $1
       AND is_active = true
       AND (event_types @> $2::jsonb OR event_types = '["*"]'::jsonb)
     ORDER BY priority ASC`,
    [tenantId, JSON.stringify([eventType])]
  );
  return result.rows;
}

export function evaluateRules(
  rules: DefenseRule[],
  payload: Record<string, unknown>
): RuleEvalResult[] {
  return rules.map((rule) => {
    const results = rule.conditions.map((c) => evalCondition(c, payload));
    const matched =
      rule.conditionLogic === "AND" ? results.every(Boolean) : results.some(Boolean);
    return { ruleId: rule.id, ruleName: rule.name, matched, action: rule.action };
  });
}

import type { Pool } from "pg";
import type Redis from "ioredis";

export interface FoodDefenseEvent {
