// Base weights per event type
const EVENT_TYPE_WEIGHTS: Record<string, number> = {
  "access.unauthorized":        90,
  "access.after-hours":         60,
  "tamper.packaging":           85,
  "tamper.seal":                80,
  "ingredient.substitution":    75,
  "temperature.excursion":      65,
  "chemical.detection":         95,
  "allergen.cross-contact":     70,
  "employee.behavior.anomaly":  55,
  "supply-chain.gap":           50,
  "foreign-object.detected":    88,
  "pest.detection":             72,
  "recall.trigger":             92,
  "batch.deviation":            60,
  "audit.failure":              68,
};

// Severity multipliers
const SEVERITY_MULTIPLIERS: Record<string, number> = {
  low: 0.4,
  medium: 0.65,
  high: 0.85,
  critical: 1.0,
};

export async function computeThreatScore(
  event: FoodDefenseEvent,
  db: Pool,
  redis: Redis
): Promise<ThreatScore> {
  const factors: ScoreFactor[] = [];

  // Factor 1: event type base weight
  const typeWeight = EVENT_TYPE_WEIGHTS[event.eventType] ?? 40;
  const severityMult = SEVERITY_MULTIPLIERS[event.severity] ?? 0.5;
  const typeContribution = typeWeight * severityMult;
  factors.push({
    name: "event_type_severity",
    weight: typeWeight,
    value: severityMult,
    contribution: typeContribution,
  });

  // Factor 2: frequency — how many similar events in the window
  const windowKey = `fd:freq:${event.tenantId}:${event.facilityId}:${event.eventType}`;
  const freq = parseInt((await redis.get(windowKey)) ?? "0", 10);
  const freqScore = Math.min(freq * 5, 30); // cap at 30 pts
  await redis.multi().incr(windowKey).expire(windowKey, 3600).exec();
  factors.push({
    name: "event_frequency",
    weight: 30,
    value: freq,
    contribution: freqScore,
  });

  // Factor 3: facility risk profile from DB
  const facilityResult = await db.query(
    `SELECT risk_profile_score FROM facilities WHERE id = $1 AND tenant_id = $2`,
    [event.facilityId, event.tenantId]
  );
  const facilityRisk = facilityResult.rowCount! > 0 ? facilityResult.rows[0].risk_profile_score : 50;
  const facilityContribution = (facilityRisk / 100) * 15; // up to 15 pts
  factors.push({
    name: "facility_risk_profile",
    weight: 15,
    value: facilityRisk,
    contribution: facilityContribution,
  });

  // Aggregate
  const rawScore = Math.min(typeContribution + freqScore + facilityContribution, 100);
  const score = Math.round(rawScore);

  let level: ThreatScore["level"];
  let recommendation: string;
  if (score >= 85) {
    level = "red";
    recommendation = "Immediate escalation required. Isolate affected batch and initiate recall protocol.";
  } else if (score >= 65) {
    level = "orange";
    recommendation = "Elevated threat detected. Notify food safety officer and begin containment review.";
  } else if (score >= 40) {
    level = "yellow";
    recommendation = "Moderate concern. Document event and increase monitoring frequency.";
  } else {
    level = "green";
    recommendation = "Low threat level. Log for audit trail and continue normal operations.";
  }

  return { score, level, factors, recommendation };
}

export function shouldTriggerAlert(score: ThreatScore, threshold: number): boolean {
  return score.score >= threshold;
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";

const UpdateAlertSchema = z.object({
  status: z.enum(["open", "acknowledged", "resolved", "false-positive"]),
  resolution: z.string().max(1000).optional(),
});

export async function alertRoutes(app: FastifyInstance) {
  const db   = (app as any).db;
  const nats = (app as any).nats;

  app.get("/", async (req, reply) => {
    const tenantId = req.headers["x-tenant-id"] as string;
    const { status, severity, facilityId, page = "1", limit = "50" } = req.query as Record<string, string>;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    const filters = ["tenant_id = $1"];
    const params: unknown[] = [tenantId];

    if (status)     { params.push(status);     filters.push(`status = $${params.length}`); }
    if (severity)   { params.push(severity);   filters.push(`severity = $${params.length}`); }
    if (facilityId) { params.push(facilityId); filters.push(`facility_id = $${params.length}`); }

    params.push(parseInt(limit), offset);

    const result = await db.query(
      `SELECT id, facility_id, alert_type, severity, threat_score, threat_level,
              message, status, created_at, resolved_at
       FROM food_defense_alerts
       WHERE ${filters.join(" AND ")}
       ORDER BY created_at DESC
       LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params
    );

    return reply.send({ data: result.rows });
  });

  app.patch("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = req.headers["x-tenant-id"] as string;
    const parsed = UpdateAlertSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const { status, resolution } = parsed.data;
    const resolvedAt = ["resolved", "false-positive"].includes(status) ? new Date() : null;

    await db.query(
      `UPDATE food_defense_alerts
       SET status=$1, resolution=$2, resolved_at=$3, updated_at=NOW()
       WHERE id=$4 AND tenant_id=$5`,
      [status, resolution ?? null, resolvedAt, id, tenantId]
    );

    nats.publish("atlas.food-defense.alert.updated",
      Buffer.from(JSON.stringify({ alertId: id, tenantId, status, ts: new Date().toISOString() })));

    return reply.send({ ok: true });
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";
import { computeThreatScore } from "../modules/scoring-engine";
import { loadActiveRules, evaluateRules } from "../modules/rules-engine";
import { config } from "../lib/config";

const CreateEventSchema = z.object({
  facilityId: z.string().uuid(),
  eventType: z.string().min(1).max(128),
  severity: z.enum(["low", "medium", "high", "critical"]).default("medium"),
  payload: z.record(z.unknown()).default({}),
  sourceSystem: z.string().default("manual"),
  actorId: z.string().optional(),
});

export async function eventRoutes(app: FastifyInstance) {
  const db    = (app as any).db;
  const redis = (app as any).redis;
  const nats  = (app as any).nats;

  // POST /events
  app.post("/", async (req, reply) => {
    const parsed = CreateEventSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const tenantId = req.headers["x-tenant-id"] as string;
    if (!tenantId) return reply.code(400).send({ error: "X-Tenant-ID required" });

    const { facilityId, eventType, severity, payload, sourceSystem, actorId } = parsed.data;
    const eventId = randomUUID();

    await db.query(
      `INSERT INTO food_defense_events
         (id, tenant_id, facility_id, event_type, severity, payload, actor_id, source_system)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
      [eventId, tenantId, facilityId, eventType, severity, JSON.stringify(payload), actorId ?? null, sourceSystem]
    );

    // Score and evaluate synchronously for API callers
    const score = await computeThreatScore(
      { id: eventId, tenantId, facilityId, eventType, severity, payload, sourceSystem, ts: new Date() },
      db, redis
    );

    const rules = await loadActiveRules(db, tenantId, eventType);
    const ruleResults = evaluateRules(rules, payload);

    let alert: { id: string } | null = null;
    if (score.score >= config.THREAT_SCORE_THRESHOLD || ruleResults.some((r) => r.matched)) {
      const alertId = randomUUID();
      await db.query(
        `INSERT INTO food_defense_alerts
           (id, tenant_id, facility_id, alert_type, severity, event_id, threat_score, threat_level, message, status)
         VALUES ($1,$2,$3,'scored',$4,$5,$6,$7,$8,'open')`,
        [alertId, tenantId, facilityId, severity, eventId, score.score, score.level, score.recommendation]
      );
      alert = { id: alertId };

      nats.publish("atlas.food-defense.alert.created",
        Buffer.from(JSON.stringify({ alertId, tenantId, facilityId, eventId, threatScore: score })));
    }

    return reply.code(201).send({ id: eventId, threatScore: score, ruleResults, alert });
  });

  // GET /events
  app.get("/", async (req, reply) => {
    const tenantId = req.headers["x-tenant-id"] as string;
    const { page = "1", limit = "50", facilityId, eventType } = req.query as Record<string, string>;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    const filters: string[] = ["tenant_id = $1"];
    const params: unknown[] = [tenantId];
    if (facilityId) { params.push(facilityId); filters.push(`facility_id = $${params.length}`); }
    if (eventType)  { params.push(eventType);  filters.push(`event_type = $${params.length}`); }

    params.push(parseInt(limit), offset);
    const result = await db.query(
      `SELECT id, facility_id, event_type, severity, actor_id, source_system, anomaly_checked, created_at
       FROM food_defense_events WHERE ${filters.join(" AND ")}
       ORDER BY created_at DESC LIMIT $${params.length - 1} OFFSET $${params.length}`,
      params
    );
    return reply.send({ data: result.rows });
  });

  // GET /events/:id
  app.get("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = req.headers["x-tenant-id"] as string;
    const result = await db.query(
      `SELECT * FROM food_defense_events WHERE id = $1 AND tenant_id = $2`, [id, tenantId]
    );
    if (result.rowCount === 0) return reply.code(404).send({ error: "Event not found" });
    return reply.send(result.rows[0]);
  });
}

