import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const ConditionSchema = z.object({
  field: z.string(),
  operator: z.enum(["eq","neq","gt","gte","lt","lte","contains","in","not_in"]),
  value: z.unknown(),
});

const CreateRuleSchema = z.object({
  name: z.string().min(1).max(120),
  description: z.string().max(500).optional(),
  eventTypes: z.array(z.string()).min(1),
  conditions: z.array(ConditionSchema).min(1),
  conditionLogic: z.enum(["AND","OR"]).default("AND"),
  action: z.enum(["alert","block","flag","escalate","notify"]),
  priority: z.number().int().min(1).max(100).default(50),
});

export async function ruleRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  app.get("/", async (req, reply) => {
    const tenantId = req.headers["x-tenant-id"] as string;
    const result = await db.query(
      `SELECT id, name, description, event_types, action, priority, is_active, created_at
       FROM food_defense_rules WHERE tenant_id = $1 ORDER BY priority ASC`,
      [tenantId]
    );
    return reply.send({ data: result.rows });
  });

  app.post("/", async (req, reply) => {
    const parsed = CreateRuleSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const tenantId = req.headers["x-tenant-id"] as string;
    const { name, description, eventTypes, conditions, conditionLogic, action, priority } = parsed.data;
    const ruleId = randomUUID();

    await db.query(
      `INSERT INTO food_defense_rules
         (id, tenant_id, name, description, event_types, conditions, condition_logic, action, priority)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
      [ruleId, tenantId, name, description ?? null,
       JSON.stringify(eventTypes), JSON.stringify(conditions),
       conditionLogic, action, priority]
    );

    return reply.code(201).send({ id: ruleId, name, action, priority });
  });

  app.patch("/:id/toggle", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = req.headers["x-tenant-id"] as string;
    await db.query(
      `UPDATE food_defense_rules SET is_active = NOT is_active WHERE id=$1 AND tenant_id=$2`,
      [id, tenantId]
    );
    return reply.send({ ok: true });
  });

  app.delete("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = req.headers["x-tenant-id"] as string;
    await db.query(`DELETE FROM food_defense_rules WHERE id=$1 AND tenant_id=$2`, [id, tenantId]);
    return reply.send({ ok: true });
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { computeThreatScore } from "../modules/scoring-engine";

const ScoreSchema = z.object({
  facilityId: z.string().uuid(),
  eventType: z.string().min(1),
  severity: z.enum(["low", "medium", "high", "critical"]).default("medium"),
  payload: z.record(z.unknown()).default({}),
  sourceSystem: z.string().default("api"),
});

export async function scoreRoutes(app: FastifyInstance) {
  const db    = (app as any).db;
  const redis = (app as any).redis;

  // POST /score — score a hypothetical event without persisting
  app.post("/", async (req, reply) => {
    const parsed = ScoreSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const tenantId = req.headers["x-tenant-id"] as string;
    if (!tenantId) return reply.code(400).send({ error: "X-Tenant-ID required" });

    const { facilityId, eventType, severity, payload, sourceSystem } = parsed.data;

    const score = await computeThreatScore(
      {
        id: crypto.randomUUID(),
        tenantId,
        facilityId,
        eventType,
        severity,
        payload,
        sourceSystem,
        ts: new Date(),
      },
      db,
      redis
    );

    return reply.send({ threatScore: score, scoredAt: new Date().toISOString() });
  });
}

import Fastify from "fastify";
import { config } from "./lib/config";
import { logger } from "./lib/logger";
import { initTelemetry } from "./lib/telemetry";
import { connectDatabase } from "./lib/database";
import { connectRedis } from "./lib/redis";
import { connectNats } from "./lib/nats";
import { registerRoutes } from "./routes";
import { registerPlugins } from "./plugins";

async function bootstrap() {
  await initTelemetry("atlas-one-identity");

  const db = await connectDatabase(config.DATABASE_URL);
  const redis = await connectRedis(config.REDIS_URL);
  const nats = await connectNats(config.NATS_URL);

  const app = Fastify({
    logger: false,
    trustProxy: true,
    requestIdHeader: "x-request-id",
    genReqId: () => crypto.randomUUID(),
  });

  // Make connections available to route handlers via decorators
  app.decorate("db", db);
  app.decorate("redis", redis);
  app.decorate("nats", nats);

  await registerPlugins(app);
  await registerRoutes(app);

  app.get("/health", async () => ({
    status: "ok",
    service: "identity",
    version: "40.1.0",
    ts: new Date().toISOString(),
  }));

  app.get("/.well-known/openid-configuration", async (_req, reply) => {
    reply.send({
      issuer: config.JWT_ISSUER,
      jwks_uri: `${config.JWT_ISSUER}/.well-known/jwks.json`,
      authorization_endpoint: `${config.JWT_ISSUER}/auth/authorize`,
      token_endpoint: `${config.JWT_ISSUER}/auth/login`,
      response_types_supported: ["code", "token"],
      subject_types_supported: ["public"],
      id_token_signing_alg_values_supported: ["RS256"],
      scopes_supported: ["openid", "profile", "email", "roles"],
    });
  });

  app.setErrorHandler((err, req, reply) => {
    logger.error({ err, reqId: req.id }, "Unhandled identity error");
    reply.status(err.statusCode ?? 500).send({
      error: err.message ?? "Internal Server Error",
      code: err.code ?? "INTERNAL_ERROR",
    });
  });

  const graceful = async (signal: string) => {
    logger.info({ signal }, "Shutdown signal received");
    await app.close();
    await nats.drain();
    await redis.quit();
    process.exit(0);
  };
  process.on("SIGTERM", () => graceful("SIGTERM"));
  process.on("SIGINT", () => graceful("SIGINT"));

  await app.listen({ port: config.PORT, host: "0.0.0.0" });
  logger.info({ port: config.PORT }, "Atlas One Identity Service listening");
}

bootstrap().catch((err) => {
  logger.fatal({ err }, "Fatal startup error");
  process.exit(1);
});

