import { randomBytes, createHash } from "crypto";
import type { Pool } from "pg";

export interface ApiKey {
  id: string;
  tenantId: string;
  userId: string;
  name: string;
  prefix: string;
  keyHash: string;
  scopes: string[];
  expiresAt: Date | null;
  lastUsedAt: Date | null;
  createdAt: Date;
}

export function generateApiKey(): { raw: string; prefix: string; hash: string } {
  const raw = `atk_${randomBytes(32).toString("base64url")}`;
  const prefix = raw.slice(0, 12);
  const hash = createHash("sha256").update(raw).digest("hex");
  return { raw, prefix, hash };
}

export function hashApiKey(raw: string): string {
  return createHash("sha256").update(raw).digest("hex");
}

export async function lookupApiKey(
  db: Pool,
  raw: string
): Promise<ApiKey | null> {
  const hash = hashApiKey(raw);
  const result = await db.query<ApiKey>(
    `SELECT * FROM api_keys WHERE key_hash = $1 AND (expires_at IS NULL OR expires_at > NOW())`,
    [hash]
  );
  if (result.rowCount === 0) return null;
  // Update last_used_at asynchronously
  db.query(`UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`, [result.rows[0].id]).catch(() => {});
  return result.rows[0];
}

import { SignJWT, generateKeyPair, exportJWK, importPKCS8, importSPKI, type KeyLike } from "jose";
import { randomUUID } from "crypto";
import { config } from "../lib/config";
import { logger } from "../lib/logger";

export interface TokenPair {
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  tokenType: "Bearer";
}

export interface AccessTokenClaims {
  sub: string;
  tenantId: string;
  roles: string[];
  permissions: string[];
  sessionId: string;
  email: string;
}

let privateKey: KeyLike;
let publicKey: KeyLike;
let jwkPublic: object;
let keyId: string;

export async function initKeys(vaultPrivatePem?: string, vaultPublicPem?: string) {
  if (vaultPrivatePem && vaultPublicPem) {
    privateKey = await importPKCS8(vaultPrivatePem, "RS256");
    publicKey = await importSPKI(vaultPublicPem, "RS256");
    keyId = "atlas-v40-1";
    logger.info("JWT keys loaded from Vault");
  } else {
    // Dev mode: ephemeral keys
    const pair = await generateKeyPair("RS256", { modulusLength: 2048 });
    privateKey = pair.privateKey;
    publicKey = pair.publicKey;
    keyId = randomUUID();
    logger.warn("JWT keys generated ephemerally — do not use in production");
  }
  jwkPublic = { ...(await exportJWK(publicKey)), kid: keyId, use: "sig", alg: "RS256" };
}

export function getJwks() {
  return { keys: [jwkPublic] };
}

export async function signAccessToken(claims: AccessTokenClaims): Promise<string> {
  return new SignJWT({
    ...claims,
    "atlas:roles": claims.roles,
    "atlas:permissions": claims.permissions,
    "atlas:tenantId": claims.tenantId,
  })
    .setProtectedHeader({ alg: "RS256", kid: keyId })
    .setIssuedAt()
    .setIssuer(config.JWT_ISSUER)
    .setAudience(config.JWT_AUDIENCE)
    .setSubject(claims.sub)
    .setJti(randomUUID())
    .setExpirationTime(`${config.JWT_ACCESS_TTL}s`)
    .sign(privateKey);
}

export async function signRefreshToken(sub: string, sessionId: string): Promise<string> {
  return new SignJWT({ sessionId, type: "refresh" })
    .setProtectedHeader({ alg: "RS256", kid: keyId })
    .setIssuedAt()
    .setIssuer(config.JWT_ISSUER)
    .setAudience(`${config.JWT_AUDIENCE}:refresh`)
    .setSubject(sub)
    .setJti(randomUUID())
    .setExpirationTime(`${config.JWT_REFRESH_TTL}s`)
    .sign(privateKey);
}

import { authenticator } from "otplib";
import { randomBytes } from "crypto";
import { config } from "../lib/config";

export interface MfaEnrollment {
  secret: string;
  otpauthUrl: string;
  backupCodes: string[];
}

export function generateMfaSecret(userEmail: string): MfaEnrollment {
  const secret = authenticator.generateSecret(32);
  const otpauthUrl = authenticator.keyuri(userEmail, config.MFA_ISSUER_NAME, secret);
  const backupCodes = Array.from({ length: 8 }, () =>
    randomBytes(5).toString("hex").toUpperCase()
  );
  return { secret, otpauthUrl, backupCodes };
}

export function verifyTotp(token: string, secret: string): boolean {
  return authenticator.check(token, secret);
}

export function verifyBackupCode(code: string, hashedCodes: string[]): { valid: boolean; usedIndex: number } {
  const normalized = code.toUpperCase().replace(/\s/g, "");
  const idx = hashedCodes.findIndex((h) => h === normalized);
  return { valid: idx !== -1, usedIndex: idx };
}

import type { PoolClient } from "pg";

export interface Role {
  id: string;
  name: string;
  tenantId: string;
  permissions: string[];
  createdAt: Date;
}

export interface Permission {
  id: string;
  resource: string;
  action: string;
  scope?: string;
}

export const SYSTEM_ROLES = {
  SUPER_ADMIN: "super_admin",
  TENANT_ADMIN: "tenant_admin",
  OPERATOR: "operator",
  VIEWER: "viewer",
  AUDITOR: "auditor",
  FOOD_DEFENSE_ANALYST: "food_defense_analyst",
  PROVENANCE_WRITER: "provenance_writer",
} as const;

export const PERMISSIONS = {
  // Users
  USERS_READ: "users:read",
  USERS_WRITE: "users:write",
  USERS_DELETE: "users:delete",
  // Tenants
  TENANTS_READ: "tenants:read",
  TENANTS_WRITE: "tenants:write",
  // Provenance
  PROVENANCE_READ: "provenance:read",
  PROVENANCE_WRITE: "provenance:write",
  PROVENANCE_VERIFY: "provenance:verify",
  // Food Defense
  FOOD_DEFENSE_READ: "food_defense:read",
  FOOD_DEFENSE_WRITE: "food_defense:write",
  FOOD_DEFENSE_RULES_WRITE: "food_defense:rules:write",
  // Audit
  AUDIT_READ: "audit:read",
  // Config
  CONFIG_READ: "config:read",
  CONFIG_WRITE: "config:write",
} as const;

export type PermissionKey = (typeof PERMISSIONS)[keyof typeof PERMISSIONS];

export const ROLE_PERMISSION_MAP: Record<string, PermissionKey[]> = {
  [SYSTEM_ROLES.SUPER_ADMIN]: Object.values(PERMISSIONS),
  [SYSTEM_ROLES.TENANT_ADMIN]: [
    PERMISSIONS.USERS_READ, PERMISSIONS.USERS_WRITE, PERMISSIONS.USERS_DELETE,
    PERMISSIONS.TENANTS_READ,
    PERMISSIONS.PROVENANCE_READ, PERMISSIONS.PROVENANCE_WRITE, PERMISSIONS.PROVENANCE_VERIFY,
    PERMISSIONS.FOOD_DEFENSE_READ, PERMISSIONS.FOOD_DEFENSE_WRITE,
    PERMISSIONS.AUDIT_READ, PERMISSIONS.CONFIG_READ, PERMISSIONS.CONFIG_WRITE,
  ],
  [SYSTEM_ROLES.OPERATOR]: [
    PERMISSIONS.USERS_READ,
    PERMISSIONS.PROVENANCE_READ, PERMISSIONS.PROVENANCE_WRITE,
    PERMISSIONS.FOOD_DEFENSE_READ, PERMISSIONS.FOOD_DEFENSE_WRITE,
    PERMISSIONS.AUDIT_READ, PERMISSIONS.CONFIG_READ,
  ],
  [SYSTEM_ROLES.VIEWER]: [
    PERMISSIONS.USERS_READ,
    PERMISSIONS.PROVENANCE_READ,
    PERMISSIONS.FOOD_DEFENSE_READ,
    PERMISSIONS.AUDIT_READ,
    PERMISSIONS.CONFIG_READ,
  ],
  [SYSTEM_ROLES.AUDITOR]: [PERMISSIONS.AUDIT_READ, PERMISSIONS.PROVENANCE_READ, PERMISSIONS.PROVENANCE_VERIFY],
  [SYSTEM_ROLES.FOOD_DEFENSE_ANALYST]: [
    PERMISSIONS.FOOD_DEFENSE_READ, PERMISSIONS.FOOD_DEFENSE_WRITE, PERMISSIONS.FOOD_DEFENSE_RULES_WRITE,
    PERMISSIONS.AUDIT_READ,
  ],
  [SYSTEM_ROLES.PROVENANCE_WRITER]: [
    PERMISSIONS.PROVENANCE_READ, PERMISSIONS.PROVENANCE_WRITE, PERMISSIONS.PROVENANCE_VERIFY,
  ],
};

export function resolvePermissions(roles: string[]): PermissionKey[] {
  const perms = new Set<PermissionKey>();
  for (const role of roles) {
    for (const perm of ROLE_PERMISSION_MAP[role] ?? []) {
      perms.add(perm);
    }
  }
  return [...perms];
}

export async function getRolesByUser(db: PoolClient, userId: string, tenantId: string): Promise<string[]> {
  const result = await db.query<{ role_name: string }>(
    `SELECT r.name AS role_name
     FROM user_roles ur
     JOIN roles r ON r.id = ur.role_id
     WHERE ur.user_id = $1 AND ur.tenant_id = $2`,
    [userId, tenantId]
  );
  return result.rows.map((r) => r.role_name);
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";
import { generateApiKey } from "../modules/apikeys";

const CreateApiKeySchema = z.object({
  name: z.string().min(1).max(120),
  scopes: z.array(z.string()).default([]),
  expiresInDays: z.number().int().min(1).max(365).optional(),
});

export async function apiKeyRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  app.get("/", async (req, reply) => {
    const principal = (req as any).principal;
    const result = await db.query(
      `SELECT id, name, prefix, scopes, expires_at, last_used_at, created_at
       FROM api_keys WHERE user_id = $1 AND tenant_id = $2 AND revoked = false
       ORDER BY created_at DESC`,
      [principal.sub, principal.tenantId]
    );
    return reply.send({ data: result.rows });
  });

  app.post("/", async (req, reply) => {
    const parsed = CreateApiKeySchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const principal = (req as any).principal;
    const { name, scopes, expiresInDays } = parsed.data;
    const { raw, prefix, hash } = generateApiKey();
    const keyId = randomUUID();

    const expiresAt = expiresInDays
      ? new Date(Date.now() + expiresInDays * 86_400_000)
      : null;

    await db.query(
      `INSERT INTO api_keys (id, user_id, tenant_id, name, prefix, key_hash, scopes, expires_at)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
      [keyId, principal.sub, principal.tenantId, name, prefix, hash,
       JSON.stringify(scopes), expiresAt]
    );

    // Return the raw key ONCE — it will never be retrievable again
    return reply.code(201).send({ id: keyId, name, prefix, key: raw, scopes, expiresAt });
  });

  app.delete("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const principal = (req as any).principal;
    await db.query(
      `UPDATE api_keys SET revoked=true WHERE id=$1 AND user_id=$2 AND tenant_id=$3`,
      [id, principal.sub, principal.tenantId]
    );
    return reply.send({ ok: true });
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import argon2 from "argon2";
import { signAccessToken, signRefreshToken } from "../modules/jwt";
import { resolvePermissions } from "../modules/rbac";
import { verifyTotp } from "../modules/mfa";
import { logger } from "../lib/logger";
import { config } from "../lib/config";
import { randomUUID } from "crypto";

const LoginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  tenantId: z.string().uuid(),
  mfaToken: z.string().length(6).optional(),
});

const RefreshSchema = z.object({
  refreshToken: z.string(),
});

const MfaEnrollSchema = z.object({ tenantId: z.string().uuid() });
const MfaVerifySchema = z.object({ token: z.string().length(6) });

export async function authRoutes(app: FastifyInstance) {
  const db   = (app as any).db;
  const redis = (app as any).redis;
  const nats  = (app as any).nats;

  // POST /auth/login
  app.post("/login", async (req, reply) => {
    const parsed = LoginSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }
    const { email, password, tenantId, mfaToken } = parsed.data;

    // Lockout check
    const lockKey = `lockout:${tenantId}:${email}`;
    const attempts = parseInt((await redis.get(lockKey)) ?? "0", 10);
    if (attempts >= config.ACCOUNT_LOCKOUT_ATTEMPTS) {
      return reply.code(429).send({ error: "Account temporarily locked", code: "ACCOUNT_LOCKED" });
    }

    const result = await db.query(
      `SELECT u.id, u.email, u.password_hash, u.mfa_enabled, u.mfa_secret,
              coalesce(array_agg(r.name) FILTER (WHERE r.name IS NOT NULL), '{}') AS roles
       FROM users u
       LEFT JOIN user_roles ur ON ur.user_id = u.id AND ur.tenant_id = $2
       LEFT JOIN roles r ON r.id = ur.role_id
       WHERE u.email = $1 AND u.tenant_id = $2 AND u.is_active = true
       GROUP BY u.id`,
      [email, tenantId]
    );

    const incLock = () =>
      redis.multi().incr(lockKey).expire(lockKey, config.ACCOUNT_LOCKOUT_WINDOW_SECS).exec();

    if (result.rowCount === 0) {
      await incLock();
      return reply.code(401).send({ error: "Invalid credentials", code: "INVALID_CREDENTIALS" });
    }

    const user = result.rows[0];
    const valid = await argon2.verify(user.password_hash, password);
    if (!valid) {
      await incLock();
      return reply.code(401).send({ error: "Invalid credentials", code: "INVALID_CREDENTIALS" });
    }

    if (user.mfa_enabled) {
      if (!mfaToken) return reply.code(200).send({ mfaRequired: true });
      if (!verifyTotp(mfaToken, user.mfa_secret)) {
        return reply.code(401).send({ error: "Invalid MFA token", code: "MFA_INVALID" });
      }
    }

    await redis.del(lockKey);

    const roles = user.roles as string[];
    const permissions = resolvePermissions(roles);
    const sessionId = randomUUID();

    const [accessToken, refreshToken] = await Promise.all([
      signAccessToken({ sub: user.id, tenantId, roles, permissions, sessionId, email: user.email }),
      signRefreshToken(user.id, sessionId),
    ]);

    await Promise.all([
      redis.setex(`session:${sessionId}`, config.JWT_REFRESH_TTL,
        JSON.stringify({ userId: user.id, tenantId, roles, sessionId })),
      db.query(
        `INSERT INTO refresh_tokens (id, user_id, tenant_id, session_id, token_hash, expires_at)
         VALUES ($1,$2,$3,$4,encode(sha256($5::bytea),'hex'),
                 NOW() + ($6 || ' seconds')::interval)`,
        [randomUUID(), user.id, tenantId, sessionId, refreshToken, config.JWT_REFRESH_TTL]
      ),
    ]);

    logger.info({ userId: user.id, tenantId, sessionId }, "Login successful");
    nats.publish("atlas.identity.login",
      Buffer.from(JSON.stringify({ userId: user.id, tenantId, sessionId, ts: new Date() })));

    return reply.send({ accessToken, refreshToken, expiresIn: config.JWT_ACCESS_TTL, tokenType: "Bearer" });
  });

  // POST /auth/refresh
  app.post("/refresh", async (req, reply) => {
    const parsed = RefreshSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed" });

    const { refreshToken } = parsed.data;
    const hash = require("crypto").createHash("sha256").update(refreshToken).digest("hex");

    const result = await db.query(
      `SELECT rt.*, u.email,
              coalesce(array_agg(r.name) FILTER (WHERE r.name IS NOT NULL), '{}') AS roles
       FROM refresh_tokens rt
       JOIN users u ON u.id = rt.user_id
       LEFT JOIN user_roles ur ON ur.user_id = rt.user_id AND ur.tenant_id = rt.tenant_id
       LEFT JOIN roles r ON r.id = ur.role_id
       WHERE rt.token_hash = $1 AND rt.revoked = false AND rt.expires_at > NOW()
       GROUP BY rt.id, u.email`,
      [hash]
    );

    if (result.rowCount === 0) {
      return reply.code(401).send({ error: "Invalid or expired refresh token", code: "TOKEN_INVALID" });
    }

    const rt = result.rows[0];
    const roles = rt.roles as string[];
    const permissions = resolvePermissions(roles);
    const newSessionId = randomUUID();

    const [newAccess, newRefresh] = await Promise.all([
      signAccessToken({ sub: rt.user_id, tenantId: rt.tenant_id, roles, permissions, sessionId: newSessionId, email: rt.email }),
      signRefreshToken(rt.user_id, newSessionId),
    ]);

    // Rotate: revoke old, insert new
    await Promise.all([
      db.query(`UPDATE refresh_tokens SET revoked=true WHERE id=$1`, [rt.id]),
      db.query(
        `INSERT INTO refresh_tokens (id,user_id,tenant_id,session_id,token_hash,expires_at)
         VALUES ($1,$2,$3,$4,encode(sha256($5::bytea),'hex'),NOW()+($6||' seconds')::interval)`,
        [randomUUID(), rt.user_id, rt.tenant_id, newSessionId, newRefresh, config.JWT_REFRESH_TTL]
      ),
      redis.setex(`session:${newSessionId}`, config.JWT_REFRESH_TTL,
        JSON.stringify({ userId: rt.user_id, tenantId: rt.tenant_id, roles, sessionId: newSessionId })),
    ]);

    return reply.send({ accessToken: newAccess, refreshToken: newRefresh, expiresIn: config.JWT_ACCESS_TTL, tokenType: "Bearer" });
  });

  // POST /auth/logout
  app.post("/logout", async (req, reply) => {
    const sessionId = (req as any).principal?.sessionId;
    if (sessionId) {
      await Promise.all([
        redis.del(`session:${sessionId}`),
        db.query(`UPDATE refresh_tokens SET revoked=true WHERE session_id=$1`, [sessionId]),
      ]);
    }
    return reply.send({ ok: true });
  });

  // POST /auth/mfa/enroll
  app.post("/mfa/enroll", async (req, reply) => {
    const parsed = MfaEnrollSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed" });
    const sub = (req as any).principal?.sub;
    if (!sub) return reply.code(401).send({ error: "Unauthorized" });

    const userResult = await db.query(`SELECT email FROM users WHERE id=$1`, [sub]);
    if (userResult.rowCount === 0) return reply.code(404).send({ error: "User not found" });

    const { generateMfaSecret } = await import("../modules/mfa");
    const enrollment = generateMfaSecret(userResult.rows[0].email);

    // Store secret temporarily until verified
    await redis.setex(`mfa_pending:${sub}`, 300, enrollment.secret);

    return reply.send({ otpauthUrl: enrollment.otpauthUrl, backupCodes: enrollment.backupCodes });
  });

  // POST /auth/mfa/verify
  app.post("/mfa/verify", async (req, reply) => {
    const parsed = MfaVerifySchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed" });
    const sub = (req as any).principal?.sub;
    if (!sub) return reply.code(401).send({ error: "Unauthorized" });

    const pendingSecret = await redis.get(`mfa_pending:${sub}`);
    if (!pendingSecret) return reply.code(400).send({ error: "No pending MFA enrollment" });

    if (!verifyTotp(parsed.data.token, pendingSecret)) {
      return reply.code(400).send({ error: "Invalid TOTP token" });
    }

    await Promise.all([
      db.query(`UPDATE users SET mfa_enabled=true, mfa_secret=$1 WHERE id=$2`, [pendingSecret, sub]),
      redis.del(`mfa_pending:${sub}`),
    ]);

    return reply.send({ ok: true, message: "MFA enabled successfully" });
  });
}

import type { FastifyInstance } from "fastify";
import { authRoutes } from "./auth";
import { userRoutes } from "./users";
import { tenantRoutes } from "./tenants";
import { roleRoutes } from "./roles";
import { apiKeyRoutes } from "./apikeys";
import { jwksRoutes } from "./jwks";

export async function registerRoutes(app: FastifyInstance) {
  await app.register(authRoutes,   { prefix: "/auth" });
  await app.register(userRoutes,   { prefix: "/users" });
  await app.register(tenantRoutes, { prefix: "/tenants" });
  await app.register(roleRoutes,   { prefix: "/roles" });
  await app.register(apiKeyRoutes, { prefix: "/api-keys" });
  await app.register(jwksRoutes,   { prefix: "/.well-known" });
}

import type { FastifyInstance } from "fastify";
import { getJwks } from "../modules/jwt";

export async function jwksRoutes(app: FastifyInstance) {
  app.get("/jwks.json", async (_req, reply) => {
    reply.header("Cache-Control", "public, max-age=600");
    return reply.send(getJwks());
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";
import { ROLE_PERMISSION_MAP } from "../modules/rbac";

const CreateRoleSchema = z.object({
  name: z.string().regex(/^[a-z_]+$/).min(2).max(64),
  description: z.string().max(255).optional(),
  permissions: z.array(z.string()).optional(),
});

export async function roleRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  app.get("/", async (req, reply) => {
    const tenantId = (req as any).principal?.tenantId;
    const result = await db.query(
      `SELECT id, name, description, permissions, created_at
       FROM roles WHERE tenant_id = $1 OR tenant_id IS NULL
       ORDER BY name`,
      [tenantId]
    );
    return reply.send({ data: result.rows });
  });

  app.post("/", async (req, reply) => {
    const parsed = CreateRoleSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const tenantId = (req as any).principal?.tenantId;
    const { name, description, permissions } = parsed.data;
    const resolvedPerms = permissions ?? ROLE_PERMISSION_MAP[name] ?? [];
    const roleId = randomUUID();

    await db.query(
      `INSERT INTO roles (id, name, description, permissions, tenant_id) VALUES ($1,$2,$3,$4,$5)`,
      [roleId, name, description ?? null, JSON.stringify(resolvedPerms), tenantId]
    );

    return reply.code(201).send({ id: roleId, name, permissions: resolvedPerms });
  });

  app.delete("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = (req as any).principal?.tenantId;
    await db.query(`DELETE FROM roles WHERE id=$1 AND tenant_id=$2`, [id, tenantId]);
    return reply.send({ ok: true });
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";

const CreateTenantSchema = z.object({
  name: z.string().min(2).max(120),
  slug: z.string().regex(/^[a-z0-9-]+$/).min(2).max(64),
  plan: z.enum(["starter", "professional", "enterprise"]).default("starter"),
  metadata: z.record(z.string()).optional(),
});

export async function tenantRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  app.get("/", async (req, reply) => {
    const principal = (req as any).principal;
    if (!principal?.roles.includes("super_admin")) {
      return reply.code(403).send({ error: "Super admin only" });
    }
    const result = await db.query(
      `SELECT id, name, slug, plan, is_active, created_at FROM tenants ORDER BY created_at DESC LIMIT 100`
    );
    return reply.send({ data: result.rows });
  });

  app.post("/", async (req, reply) => {
    const parsed = CreateTenantSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const { name, slug, plan, metadata } = parsed.data;
    const tenantId = randomUUID();

    await db.query(
      `INSERT INTO tenants (id, name, slug, plan, metadata) VALUES ($1,$2,$3,$4,$5)`,
      [tenantId, name, slug, plan, JSON.stringify(metadata ?? {})]
    );

    // Seed default roles for tenant
    const defaultRoles = ["tenant_admin", "operator", "viewer", "auditor", "food_defense_analyst", "provenance_writer"];
    for (const roleName of defaultRoles) {
      await db.query(
        `INSERT INTO roles (id, name, tenant_id) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING`,
        [randomUUID(), roleName, tenantId]
      );
    }

    return reply.code(201).send({ id: tenantId, name, slug, plan });
  });

  app.get("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const result = await db.query(
      `SELECT id, name, slug, plan, is_active, metadata, created_at FROM tenants WHERE id = $1`,
      [id]
    );
    if (result.rowCount === 0) return reply.code(404).send({ error: "Tenant not found" });
    return reply.send(result.rows[0]);
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import argon2 from "argon2";
import { randomUUID } from "crypto";

const CreateUserSchema = z.object({
  email: z.string().email(),
  password: z.string().min(12),
  firstName: z.string().min(1).max(100),
  lastName: z.string().min(1).max(100),
  tenantId: z.string().uuid(),
  roles: z.array(z.string()).default([]),
});

const UpdateUserSchema = z.object({
  firstName: z.string().min(1).max(100).optional(),
  lastName: z.string().min(1).max(100).optional(),
  isActive: z.boolean().optional(),
  roles: z.array(z.string()).optional(),
});

export async function userRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  // GET /users
  app.get("/", async (req, reply) => {
    const tenantId = (req as any).principal?.tenantId ?? req.headers["x-tenant-id"];
    if (!tenantId) return reply.code(400).send({ error: "Tenant context required" });

    const { page = "1", limit = "25" } = req.query as Record<string, string>;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    const result = await db.query(
      `SELECT u.id, u.email, u.first_name, u.last_name, u.is_active, u.created_at,
              coalesce(array_agg(r.name) FILTER (WHERE r.name IS NOT NULL), '{}') AS roles
       FROM users u
       LEFT JOIN user_roles ur ON ur.user_id = u.id AND ur.tenant_id = $1
       LEFT JOIN roles r ON r.id = ur.role_id
       WHERE u.tenant_id = $1
       GROUP BY u.id
       ORDER BY u.created_at DESC
       LIMIT $2 OFFSET $3`,
      [tenantId, parseInt(limit), offset]
    );

    const count = await db.query(`SELECT count(*) FROM users WHERE tenant_id = $1`, [tenantId]);
    return reply.send({
      data: result.rows,
      pagination: { page: parseInt(page), limit: parseInt(limit), total: parseInt(count.rows[0].count) },
    });
  });

  // POST /users
  app.post("/", async (req, reply) => {
    const parsed = CreateUserSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });

    const { email, password, firstName, lastName, tenantId, roles } = parsed.data;
    const passwordHash = await argon2.hash(password, { type: argon2.argon2id, memoryCost: 65536, timeCost: 3 });
    const userId = randomUUID();

    const client = await db.connect();
    try {
      await client.query("BEGIN");
      await client.query(
        `INSERT INTO users (id, email, password_hash, first_name, last_name, tenant_id)
         VALUES ($1,$2,$3,$4,$5,$6)`,
        [userId, email, passwordHash, firstName, lastName, tenantId]
      );

      for (const roleName of roles) {
        const roleResult = await client.query(
          `SELECT id FROM roles WHERE name = $1 AND (tenant_id = $2 OR tenant_id IS NULL)`,
          [roleName, tenantId]
        );
        if (roleResult.rowCount > 0) {
          await client.query(
            `INSERT INTO user_roles (user_id, role_id, tenant_id) VALUES ($1,$2,$3)`,
            [userId, roleResult.rows[0].id, tenantId]
          );
        }
      }

      await client.query("COMMIT");
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }

    return reply.code(201).send({ id: userId, email, firstName, lastName, tenantId, roles });
  });

  // GET /users/:id
  app.get("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = (req as any).principal?.tenantId;

    const result = await db.query(
      `SELECT u.id, u.email, u.first_name, u.last_name, u.is_active, u.mfa_enabled, u.created_at,
              coalesce(array_agg(r.name) FILTER (WHERE r.name IS NOT NULL), '{}') AS roles
       FROM users u
       LEFT JOIN user_roles ur ON ur.user_id = u.id AND ur.tenant_id = $2
       LEFT JOIN roles r ON r.id = ur.role_id
       WHERE u.id = $1 AND u.tenant_id = $2
       GROUP BY u.id`,
      [id, tenantId]
    );

    if (result.rowCount === 0) return reply.code(404).send({ error: "User not found" });
    return reply.send(result.rows[0]);
  });

  // PATCH /users/:id
  app.patch("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const parsed = UpdateUserSchema.safeParse(req.body);
    if (!parsed.success) return reply.code(400).send({ error: "Validation failed" });

    const tenantId = (req as any).principal?.tenantId;
    const { firstName, lastName, isActive } = parsed.data;

    await db.query(
      `UPDATE users SET
         first_name = COALESCE($1, first_name),
         last_name  = COALESCE($2, last_name),
         is_active  = COALESCE($3, is_active),
         updated_at = NOW()
       WHERE id = $4 AND tenant_id = $5`,
      [firstName, lastName, isActive, id, tenantId]
    );

    return reply.send({ ok: true });
  });

  // DELETE /users/:id
  app.delete("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = (req as any).principal?.tenantId;
    await db.query(`UPDATE users SET is_active=false, updated_at=NOW() WHERE id=$1 AND tenant_id=$2`, [id, tenantId]);
    return reply.send({ ok: true });
  });
}

import Fastify from "fastify";
import { config } from "./lib/config";
import { logger } from "./lib/logger";
import { initTelemetry } from "./lib/telemetry";
import { connectDatabase } from "./lib/database";
import { connectNats } from "./lib/nats";
import { registerRoutes } from "./routes";
import { startAnchorWorker } from "./modules/anchor-worker";

async function bootstrap() {
  await initTelemetry("atlas-one-provenance");

  const db   = await connectDatabase(config.DATABASE_URL);
  const nats = await connectNats(config.NATS_URL);

  const app = Fastify({
    logger: false,
    trustProxy: true,
    requestIdHeader: "x-request-id",
    genReqId: () => crypto.randomUUID(),
  });

  app.decorate("db", db);
  app.decorate("nats", nats);

  await registerRoutes(app);

  app.get("/health", async () => ({
    status: "ok", service: "provenance", version: "40.1.0",
    ts: new Date().toISOString(),
  }));

  app.setErrorHandler((err, req, reply) => {
    logger.error({ err, reqId: req.id }, "Provenance unhandled error");
    reply.status(err.statusCode ?? 500).send({ error: err.message ?? "Internal Server Error" });
  });

  // Start background periodic anchor worker
  startAnchorWorker(db, nats, config.ANCHOR_INTERVAL_MS);

  const graceful = async () => {
    await app.close();
    await nats.drain();
    process.exit(0);
  };
  process.on("SIGTERM", graceful);
  process.on("SIGINT", graceful);

  await app.listen({ port: config.PORT, host: "0.0.0.0" });
  logger.info({ port: config.PORT }, "Atlas One Provenance Service listening");
}

bootstrap().catch((err) => {
  logger.fatal({ err }, "Fatal startup error");
  process.exit(1);
});

