import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { randomUUID } from "crypto";
import { appendRecord, getChainHead } from "../modules/chain";

const CreateRecordSchema = z.object({
  entityType: z.string().min(1).max(64),
  entityId: z.string().uuid(),
  eventType: z.string().min(1).max(128),
  payload: z.record(z.unknown()),
});

export async function recordRoutes(app: FastifyInstance) {
  const db = (app as any).db;
  const nats = (app as any).nats;

  // POST /records
  app.post("/", async (req, reply) => {
    const parsed = CreateRecordSchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const tenantId = req.headers["x-tenant-id"] as string;
    const actorId  = req.headers["x-principal-sub"] as string;

    if (!tenantId) return reply.code(400).send({ error: "X-Tenant-ID required" });

    const record = await appendRecord(db, {
      id: randomUUID(),
      tenantId,
      actorId: actorId ?? "system",
      ...parsed.data,
      payload: parsed.data.payload as Record<string, unknown>,
    });

    nats.publish("atlas.provenance.record.created",
      Buffer.from(JSON.stringify({ id: record.id, tenantId, entityType: record.entityType, entityId: record.entityId })));

    return reply.code(201).send(record);
  });

  // GET /records/:id
  app.get("/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = req.headers["x-tenant-id"] as string;

    const result = await db.query(
      `SELECT * FROM provenance_records WHERE id = $1 AND tenant_id = $2`,
      [id, tenantId]
    );
    if (result.rowCount === 0) return reply.code(404).send({ error: "Record not found" });
    return reply.send(result.rows[0]);
  });

  // GET /records/:id/chain — full chain for the entity this record belongs to
  app.get("/:id/chain", async (req, reply) => {
    const { id } = req.params as { id: string };
    const tenantId = req.headers["x-tenant-id"] as string;

    const anchor = await db.query(
      `SELECT entity_type, entity_id FROM provenance_records WHERE id = $1 AND tenant_id = $2`,
      [id, tenantId]
    );
    if (anchor.rowCount === 0) return reply.code(404).send({ error: "Record not found" });

    const { entity_type, entity_id } = anchor.rows[0];
    const chain = await db.query(
      `SELECT id, event_type, hash, previous_hash, sequence_number, anchored, created_at
       FROM provenance_records
       WHERE tenant_id = $1 AND entity_type = $2 AND entity_id = $3
       ORDER BY sequence_number ASC`,
      [tenantId, entity_type, entity_id]
    );

    return reply.send({
      entityType: entity_type,
      entityId: entity_id,
      length: chain.rowCount,
      records: chain.rows,
    });
  });
}

import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { verifyChain } from "../modules/chain";

const VerifySchema = z.object({
  entityType: z.string().min(1),
  entityId: z.string().uuid(),
});

export async function verifyRoutes(app: FastifyInstance) {
  const db = (app as any).db;

  app.post("/", async (req, reply) => {
    const parsed = VerifySchema.safeParse(req.body);
    if (!parsed.success) {
      return reply.code(400).send({ error: "Validation failed", details: parsed.error.flatten() });
    }

    const tenantId = req.headers["x-tenant-id"] as string;
    if (!tenantId) return reply.code(400).send({ error: "X-Tenant-ID required" });

    const result = await verifyChain(db, tenantId, parsed.data.entityType, parsed.data.entityId);
    return reply.send({
      ...result,
      entityType: parsed.data.entityType,
      entityId: parsed.data.entityId,
      verifiedAt: new Date().toISOString(),
    });
  });
}

